/* Series glossary schema v1: ko, en, abbr, def, chapters[]; optional category, related, audio, examples, stage.
   This is the source of truth for both the glossary page and prose tooltips. */
window.BOOK_GLOSSARY = {
  version: 1,
  terms: [
    {"ko":"광자","en":"Photon","abbr":"","def":"빛 에너지의 최소 단위. 에너지 E = hc/λ로 550 nm 광자는 약 2.25 eV다. 이미지 센서는 결국 픽셀에 도달한 광자 수를 센다.","chapters":["light"]},
    {"ko":"파장","en":"Wavelength","abbr":"λ","def":"전자기파의 한 주기 길이. 가시광은 약 380~780 nm이고, 실리콘 센서는 약 1100 nm까지 반응한다.","chapters":["light"]},
    {"ko":"조도","en":"Illuminance","abbr":"lux","def":"면에 입사하는 광속 밀도(lm/m² = lux). 사람 눈의 명소시 감도 V(λ)로 가중한 양이다. 맑은 낮 약 10만 lux, 사무실 300~500 lux, 보름달 밤 약 0.2 lux.","chapters":["light"]},
    {"ko":"광속","en":"Luminous flux","abbr":"lm","def":"광원이 내는 빛을 눈의 감도로 가중한 총량(루멘). 555 nm에서 1 W = 683 lm이다.","chapters":["light"]},
    {"ko":"복사 조도","en":"Irradiance","abbr":"","def":"면에 입사하는 복사 에너지 밀도(W/m²). 눈의 감도 가중이 없는 물리량으로, 광자 선속으로 바로 환산할 수 있다.","chapters":["light"]},
    {"ko":"광자 선속","en":"Photon flux","abbr":"","def":"단위 시간·단위 면적당 도달하는 광자 수(photons/s/m²). 복사 조도를 광자 한 개의 에너지 hc/λ로 나누어 얻는다.","chapters":["light"]},
    {"ko":"분광 분포","en":"Spectral power distribution","abbr":"SPD","def":"광원의 파장별 세기 분포. 같은 lux라도 SPD가 다르면 센서가 받는 광자 수와 색이 달라진다.","chapters":["light"]},
    {"ko":"색온도","en":"Correlated color temperature","abbr":"CCT","def":"광원의 색도와 가장 가까운 흑체(플랑크 궤적 위 점)의 온도(K). CIE 1960 (u,v)에서 거리를 재며, 궤적에서 벗어난 정도는 Duv로 따로 나타낸다. 백열등 약 2700 K, 주광 D65 약 6504 K.","chapters":["light"]},
    {"ko":"발광 효율","en":"Luminous efficacy of radiation","abbr":"LER","def":"복사 1 W가 만드는 광속(lm/W). 555 nm 단색이 최대 683 lm/W이고, D65 주광은 약 205, 백색 LED는 약 300, 저압 나트륨등은 약 520 lm/W다. 클수록 같은 lux에 광자가 적다.","chapters":["light"]},
    {"ko":"플랑크 궤적","en":"Planckian locus","abbr":"","def":"온도를 바꿔 가며 흑체 스펙트럼의 색도를 이은 곡선. 백색 광원의 CCT와 Duv를 이 곡선을 기준으로 정한다.","chapters":["light"]},
    {"ko":"휘도","en":"Luminance","abbr":"cd/m²","def":"면의 단위 면적·단위 입체각당 광도(cd/m², nit). 렌즈가 보는 양이라 거리와 무관하며, 센서면 조도는 πLT/(4N²)로 휘도에 비례한다. 맑은 날 장면 평균은 약 4,000 cd/m².","chapters":["light"]},
    {"ko":"에어 매스","en":"Air mass","abbr":"AM","def":"햇빛이 지나는 대기 두께를 천정 방향 두께로 나눈 값. 약 1/sin(태양 고도)로, 고도 30°에서 2다. 대기 투과는 exp(−m·τ(λ))로 줄어든다.","chapters":["light"]},
    {"ko":"레일리 산란","en":"Rayleigh scattering","abbr":"","def":"파장보다 훨씬 작은 공기 분자에 의한 산란으로 세기가 λ⁻⁴에 비례한다. 450 nm가 650 nm보다 약 4.5배 강하게 흩어져 하늘이 파랗고 노을이 붉다.","chapters":["light"]},
    {"ko":"카메라 방정식","en":"Camera equation","abbr":"","def":"장면 휘도 L에서 센서면 조도를 주는 식 E = πLT·cos⁴θ / (4N²(1+m)²). 여기에 노출 시간, 광자 환산, QE와 픽셀 면적을 곱하면 픽셀 전자 수가 된다.","chapters":["light"]},
    {"ko":"노출값","en":"Exposure value","abbr":"EV","def":"EV = log₂(N²/t)로 정의한 노출 설정의 크기. 1 EV 차이가 빛 2배(1스톱)이고, ISO 100 기준 장면 밝기로 쓰면 맑은 날 약 EV 15, 밝은 실내 약 EV 7이다.","chapters":["light"]},
    {"ko":"파노 인자","en":"Fano factor","abbr":"F","def":"계수 분산을 평균으로 나눈 값 F = σ²/⟨k⟩. 푸아송은 1, 열광의 뭉침은 1보다 크고, 데드 타임 검출기는 약 1/(1+Rτd)²로 1보다 작다(서브푸아송).","chapters":["light"]},
    {"ko":"광자 뭉침","en":"Photon bunching","abbr":"","def":"열광에서 광자가 세기 요동이 큰 순간에 몰려 도착하는 현상. 2차 상관 g²(0) = 2이며 결맞음 시간보다 짧은 창에서만 드러난다.","chapters":["light"]},
    {"ko":"결맞음 시간","en":"Coherence time","abbr":"τc","def":"빛의 위상·세기 요동이 유지되는 시간으로 대략 λ²/(cΔλ)다. 햇빛은 약 3 fs라 이미지 센서 노출에서는 광자 통계가 사실상 푸아송이다.","chapters":["light"]},
    {"ko":"데드 타임","en":"Dead time","abbr":"τd","def":"SPAD 같은 광자 계수 검출기가 광자 하나를 센 뒤 다음 광자를 볼 수 없는 시간(수~수십 ns). 계수율이 R/(1+Rτd)로 포화되고 계수 분포가 서브푸아송이 된다.","chapters":["light"]},
    {"ko":"표준 광원","en":"Standard illuminant","abbr":"D65 / A","def":"CIE가 표로 정한 기준 분광 분포. D65는 CCT 약 6500 K 주광, A는 2856 K 흑체(백열·할로겐)로, 센서 감도·색 교정 사양의 기준 조명으로 쓴다.","chapters":["light"]},
    {"ko":"밴드갭","en":"Bandgap","abbr":"Eg","def":"가전자대와 전도대 사이의 에너지 간격. 실리콘은 1.12 eV로, 이보다 에너지가 작은(약 1.1 µm보다 긴 파장) 광자는 흡수되지 않는다.","chapters":["photodiode"]},
    {"ko":"흡수 계수","en":"Absorption coefficient","abbr":"α","def":"물질 속에서 빛의 세기가 exp(−αx)로 줄어드는 비율. 실리콘에서 청색은 매우 크고(표면 근처 흡수), 근적외선은 작아 수 µm~수십 µm까지 들어간다.","chapters":["photodiode"]},
    {"ko":"흡수 깊이","en":"Absorption depth","abbr":"1/α","def":"빛의 세기가 1/e로 줄어드는 깊이. Si에서 450 nm는 약 0.4 µm, 650 nm는 약 3 µm, 850 nm는 약 18 µm이다.","chapters":["photodiode"]},
    {"ko":"양자 효율","en":"Quantum efficiency","abbr":"QE","def":"입사한 광자 중 신호 전자로 수집되는 비율. 픽셀 QE는 반사·컬러 필터·흡수 깊이·수집 효율을 모두 곱한 값이다.","chapters":["photodiode"]},
    {"ko":"전자-정공 쌍","en":"Electron-hole pair","abbr":"EHP","def":"광자가 흡수되며 전도대로 올라간 전자와 가전자대에 남은 정공. 가시광에서는 광자 한 개가 대략 한 쌍을 만든다.","chapters":["photodiode"]},
    {"ko":"PN 접합","en":"PN junction","abbr":"","def":"p형과 n형 반도체의 경계. 내부 전계가 생겨 광생성 전자와 정공을 서로 반대 방향으로 분리한다.","chapters":["photodiode"]},
    {"ko":"공핍층","en":"Depletion region","abbr":"","def":"PN 접합 부근에서 자유 캐리어가 빠져나가 이온화된 도펀트만 남은 영역. 전계가 있어 여기서 생긴 전자를 효율적으로 수집한다.","chapters":["photodiode"]},
    {"ko":"핀드 포토다이오드","en":"Pinned photodiode","abbr":"PPD","def":"표면에 얇은 p+ 층을 두어 n 영역을 완전히 공핍시키는 포토다이오드. 표면 결함에 의한 암전류를 줄이고, 완전 전하 전송이 가능해 kTC 노이즈 없는 CDS를 가능하게 한다.","chapters":["photodiode"]},
    {"ko":"풀웰 용량","en":"Full well capacity","abbr":"FWC","def":"픽셀이 포화 전까지 저장할 수 있는 최대 전자 수. 대략 포토다이오드 면적에 비례하며 1 µm 픽셀은 수천 e⁻, 5 µm 픽셀은 수만 e⁻ 수준이다.","chapters":["photodiode"]},
    {"ko":"반응도","en":"Responsivity","abbr":"R","def":"입사 광 전력당 광전류(A/W). QE와 R = QE·qλ/(hc) 관계에 있다.","chapters":["photodiode"]},
    {"ko":"피닝 전압","en":"Pinning voltage","abbr":"V_pin","def":"전자가 하나도 없는 핀드 포토다이오드 N층의 최대 전위. 도핑 분포로 정해지며 보통 1–2 V이고, 전송 게이트·FD 전위가 이보다 충분히 높아야 전하가 남김없이 넘어간다.","chapters":["photodiode"]},
    {"ko":"평형 풀웰","en":"Equilibrium full well capacity","abbr":"EFWC","def":"PPD의 전자 준페르미 전위가 0 V(접합 무바이어스)에 이를 때까지 담을 수 있는 전자 수. 1-D 모델로 V_pin 약 1.4 V에서 약 3,000 e⁻/µm²다.","chapters":["photodiode"]},
    {"ko":"수집 확률","en":"Collection probability","abbr":"φ(z)","def":"깊이 z에서 생긴 전자가 재결합하기 전에 공핍층에 닿을 확률. 공핍층에서 1이고, IQE는 이를 광 생성 분포 αe^(−αz)와 곱해 적분한 값이다.","chapters":["photodiode"]},
    {"ko":"확산 길이","en":"Diffusion length","abbr":"L","def":"소수 캐리어가 재결합 전까지 확산하는 평균 거리 L = √(Dτ). 저도핑 에피에서는 수십~수백 µm이고, 고농도 P+ 층에서는 1 µm 미만으로 짧다.","chapters":["photodiode"]},
    {"ko":"표면 재결합 속도","en":"Surface recombination velocity","abbr":"S","def":"표면·계면에서 소수 캐리어가 사라지는 빠르기(cm/s). 잘 패시베이션된 계면은 10–100, 처리하지 않은 Si–SiO₂는 10⁵ 이상으로, 흡수 깊이가 얕은 청색 QE를 좌우한다.","chapters":["photodiode"]},
    {"ko":"개방 전압","en":"Open-circuit voltage","abbr":"V_oc","def":"빛을 받는 다이오드에 전류가 흐르지 않을 때의 전압. (kT/q)·ln(I_ph/I₀)로 광전류 10배마다 약 60 mV 오르며, 로그 픽셀의 출력 원리다.","chapters":["photodiode"]},
    {"ko":"로그 픽셀","en":"Logarithmic pixel","abbr":"","def":"광전류를 서브임계 트랜지스터나 개방 다이오드로 전압의 로그로 바꾸는 픽셀. 120 dB 이상의 다이내믹 레인지를 얻지만 저조도에서 느리고 FPN이 크다.","chapters":["photodiode"]},
    {"ko":"3T 픽셀","en":"3-transistor pixel","abbr":"3T APS","def":"포토다이오드 접합이 전하 저장과 전압 변환을 함께 하는 리셋·소스 팔로워·선택 3개 트랜지스터 픽셀. 접합 용량이 전압에 따라 변해 비선형이고, 리셋 kTC 노이즈를 CDS로 지울 수 없다.","chapters":["photodiode"]},
    {"ko":"접합 용량","en":"Junction capacitance","abbr":"C_j","def":"공핍층 양쪽 이온 전하가 만드는 용량 C_j = C_j0(1 + V/V_bi)^(−m)(계단 접합 m = 1/2). 역바이어스가 줄면 커져, 3T 픽셀의 변환 이득이 신호와 함께 30 % 안팎 떨어진다.","chapters":["photodiode"]},
    {"ko":"내장 전위","en":"Built-in potential","abbr":"V_bi","def":"평형 PN 접합 양단의 전위차 (kT/q)·ln(N_A N_D/n_i²). N_A = N_D = 10¹⁶ cm⁻³이면 약 0.72 V다.","chapters":["photodiode"]},
    {"ko":"변조 대비","en":"Demodulation contrast","abbr":"","def":"간접 ToF 픽셀이 변조된 빛 신호를 두 탭으로 얼마나 잘 갈라 내는지의 비율로, 광응답 |H(f)|/H(0)에 해당한다. 확산으로 늦게 오는 전하가 많으면 100 MHz 이상에서 크게 떨어진다.","chapters":["photodiode"]},
    {"ko":"픽셀 피치","en":"Pixel pitch","abbr":"","def":"인접 픽셀 중심 간 거리. 모바일 0.56~1.4 µm, DSLR 3~6 µm 정도이며 광자 수·FWC·해상도를 동시에 좌우한다.","chapters":["pixel"]},
    {"ko":"마이크로렌즈","en":"Microlens","abbr":"ML / OCL","def":"각 픽셀 위의 작은 렌즈. 빛을 포토다이오드 쪽으로 모아 유효 필 팩터를 높인다. 2×2 픽셀이 하나를 공유하면 PDAF에 쓸 수 있다.","chapters":["pixel"]},
    {"ko":"필 팩터","en":"Fill factor","abbr":"FF","def":"픽셀 면적 중 빛을 받는 감광 영역의 비율. FSI에서는 배선과 트랜지스터 때문에 낮아지며, 마이크로렌즈와 BSI로 보완한다.","chapters":["pixel"]},
    {"ko":"전면 조사형","en":"Front-side illumination","abbr":"FSI","def":"빛이 금속 배선층을 지나 포토다이오드에 도달하는 전통적 구조. 작은 픽셀에서 배선에 의한 가림과 광 경로 길이가 문제가 된다.","chapters":["pixel"]},
    {"ko":"이면 조사형","en":"Back-side illumination","abbr":"BSI","def":"웨이퍼를 얇게 갈아 뒤집어서 배선 반대쪽으로 빛을 받는 구조. 필 팩터와 각도 응답이 크게 좋아져 현재 소형 픽셀의 표준이다.","chapters":["pixel"]},
    {"ko":"깊은 트렌치 격리","en":"Deep trench isolation","abbr":"DTI","def":"픽셀 사이에 깊은 홈을 파 산화막·금속 등으로 채워 광학·전기적 크로스토크를 막는 구조. 뒷면에서 파는 BDTI와 앞면에서 끝까지 파는 FDTI가 있다.","chapters":["pixel"]},
    {"ko":"크로스토크","en":"Crosstalk","abbr":"","def":"한 픽셀로 들어온 빛이나 전자가 옆 픽셀 신호로 섞이는 현상. 색 혼합과 해상도 저하를 일으키며 픽셀이 작을수록 심해진다.","chapters":["pixel"]},
    {"ko":"반사 방지막","en":"Anti-reflection coating","abbr":"ARC","def":"실리콘 표면의 큰 반사(공기-Si 약 30 % 이상)를 줄이기 위한 박막 코팅. BSI 뒷면에 적용한다.","chapters":["pixel"]},
    {"ko":"전하 수집 몬테카를로","en":"Monte Carlo charge collection","abbr":"","def":"광생성 전자 하나하나를 확산(무작위 걸음)과 전계 드리프트로 3차원에서 추적해, 어느 PD에 수집되는지·후면 계면에서 재결합하는지를 통계로 세는 시뮬레이션. 전기적 크로스토크와 청색광 QE 손실을 정량화한다.","chapters":["pixel"]},
    {"ko":"내장 전계","en":"Built-in drift field","abbr":"","def":"후면 쪽 도핑 농도에 기울기를 주어 만든 전계. 전계 없는 영역을 떠도는 전자를 PD 쪽으로 밀어 수집 시간과 옆 퍼짐(전기적 크로스토크)을 줄인다.","chapters":["pixel"]},
    {"ko":"각도 응답","en":"Angular response","abbr":"","def":"입사각 θ에 따른 픽셀의 상대 감도 QE(θ)/QE(0). 마이크로렌즈 초점이 기울어 PD를 벗어나거나 그리드·DTI에 걸리면서 떨어지며, 같은 측정에서 각도별 크로스토크도 얻는다.","chapters":["pixel"]},
    {"ko":"반감 각도","en":"Half-power angle","abbr":"θ½","def":"각도 응답에서 신호가 수직 입사 대비 절반으로 떨어지는 입사각. 렌즈 F-넘버 원뿔과 CRA를 픽셀이 얼마나 받아낼 수 있는지 나타내는 지표다.","chapters":["pixel"]},
    {"ko":"광 가이드","en":"Light guide","abbr":"","def":"굴절률이 낮은 DTI 산화막으로 둘러싸인 실리콘 기둥이 전반사로 빛을 가두는 구조. NIR처럼 흡수 깊이가 픽셀보다 긴 빛을 옆 픽셀로 새지 않게 붙잡아 왕복시키며 흡수를 늘린다.","chapters":["pixel"]},
    {"ko":"경로 증대 배율","en":"Path-length enhancement","abbr":"","def":"빛이 실리콘 안에서 실제로 지나는 광로 길이를 두께로 나눈 값. DTI 광 가이드와 산란 구조가 빛을 비스듬히 여러 번 왕복시키면 커지고, NIR QE가 그만큼 오른다.","chapters":["pixel"]},
    {"ko":"좌절 전반사","en":"Frustrated total internal reflection","abbr":"FTIR","def":"전반사 조건이어도 얇은 저굴절 층 너머로 에바네센트장이 닿으면 일부가 반대편으로 투과하는 현상(광자 터널링). 누설은 대략 exp(−2κd)로 DTI 산화막 두께 d에 지수적으로 의존한다.","chapters":["pixel"]},
    {"ko":"넘침 장벽","en":"Overflow barrier","abbr":"V_b","def":"포화된 PD의 전자가 넘어가는 전위 장벽(보통 전송 게이트나 리셋 쪽). 전자의 의사 페르미 준위가 이 장벽에 닿을 때까지 담긴 전자 수가 풀웰이며, 장벽 너머로 넘친 전하는 블루밍이나 LOFIC 신호가 된다.","chapters":["pixel"]},
    {"ko":"컬러 필터 배열","en":"Color filter array","abbr":"CFA","def":"픽셀마다 한 가지 색만 통과시키는 필터 모자이크. 각 픽셀은 한 색 정보만 얻고 나머지 색은 보간으로 채운다.","chapters":["color"]},
    {"ko":"베이어 패턴","en":"Bayer pattern","abbr":"RGGB","def":"2×2 단위에 G 2개, R 1개, B 1개를 둔 가장 흔한 CFA. 사람 눈이 녹색(휘도)에 민감한 점을 반영했다.","chapters":["color"]},
    {"ko":"디모자이킹","en":"Demosaicing","abbr":"","def":"CFA 원본(RAW)의 빠진 색 성분을 주변 픽셀로 보간해 픽셀마다 RGB를 만드는 과정. 에지 방향을 고려한 적응형 보간이 쓰인다.","chapters":["color"]},
    {"ko":"분광 감도","en":"Spectral sensitivity","abbr":"","def":"파장에 따른 각 색 채널의 응답(QE) 곡선. 사람 눈의 등색 함수와 다르기 때문에 색 보정 행렬이 필요하다.","chapters":["color"]},
    {"ko":"적외선 차단 필터","en":"IR-cut filter","abbr":"IRCF","def":"약 650 nm 이상의 근적외선을 막는 필터. 실리콘이 NIR에도 반응하므로 없으면 색이 틀어진다. CCTV는 야간에 이를 빼서 NIR 감도를 쓴다.","chapters":["color"]},
    {"ko":"쿼드 베이어","en":"Quad Bayer / Tetracell","abbr":"","def":"같은 색 픽셀 2×2를 한 묶음으로 배열한 CFA. 어두울 때 4개를 합쳐 큰 픽셀처럼, 밝을 때는 리모자이크로 풀해상도를 낸다.","chapters":["color"]},
    {"ko":"모아레 · 위색","en":"Moiré / false color","abbr":"","def":"센서의 샘플링 주파수보다 가는 무늬가 낮은 주파수 줄무늬나 가짜 색으로 나타나는 앨리어싱. CFA 때문에 색 채널은 휘도보다 더 쉽게 생긴다.","chapters":["color"]},
    {"ko":"RCCB 필터","en":"Red-Clear-Clear-Blue CFA","abbr":"RCCB","def":"G 대신 필터 없는 투명(Clear) 픽셀을 쓴 CFA. 감도가 높아 차량용 저조도 센싱에 쓰지만 색 재현을 위해 복잡한 처리가 필요하다.","chapters":["color"]},
    {"ko":"색도 다이어그램","en":"Chromaticity diagram","abbr":"","def":"XYZ를 x = X/(X+Y+Z), y = Y/(X+Y+Z)로 정규화해 밝기를 뺀 색의 종류만 2차원에 나타낸 그림. CIE 1931 xy가 가장 널리 쓰인다.","chapters":["color"]},
    {"ko":"스펙트럼 궤적","en":"Spectral locus","abbr":"","def":"단색광의 색도를 파장 순으로 이은 말굽 모양 곡선. 실재하는 모든 색은 궤적과 보라선으로 둘러싸인 영역 안에 있다.","chapters":["color"]},
    {"ko":"색역","en":"Color gamut","abbr":"","def":"디스플레이나 색 공간이 표현할 수 있는 색의 범위. 가법 혼색 장치는 세 원색의 색도가 만드는 삼각형으로 나타낸다(sRGB, Display P3, Rec.2020 등).","chapters":["color"]},
    {"ko":"가상 원색","en":"Imaginary primary","abbr":"","def":"스펙트럼 궤적 밖에 놓여 실제 빛으로 만들 수 없는 원색. 카메라 CCM의 열벡터가 가리키는 '카메라 원색'은 대개 가상 원색이다.","chapters":["color"]},
    {"ko":"루터–아이브스 조건","en":"Luther–Ives condition","abbr":"","def":"카메라 분광 감도가 CIE 색 대응 함수의 선형 결합일 조건. 만족하면 3×3 행렬 하나로 모든 스펙트럼의 색을 정확히 복원할 수 있다.","chapters":["color"]},
    {"ko":"Vora–Trussell 품질 계수","en":"Vora–Trussell measure","abbr":"ν","def":"카메라 감도와 CIE 함수가 펼치는 부분공간의 일치도 ν = tr(P_X P_S)/3. 1이면 루터–아이브스 조건을 정확히 만족한다.","chapters":["color"]},
    {"ko":"메타머 블랙","en":"Metameric black","abbr":"","def":"조명 가중 색 대응 함수와 모두 직교해 더해도 XYZ가 변하지 않는 스펙트럼 성분. 메타머 쌍의 차이 스펙트럼이다.","chapters":["color"]},
    {"ko":"센서 메타메리즘","en":"Observer (camera) metamerism","abbr":"","def":"사람에게 같은 색인 두 물체를 카메라가 다르게 기록하는 현상(또는 그 반대). 감도가 루터–아이브스 조건을 만족하지 않아 생기며 3×3 CCM으로 없앨 수 없다. ISO 17321-1의 감도 메타메리즘 지수로 정량화한다.","chapters":["color"]},
    {"ko":"CCM 노이즈 이득","en":"CCM noise gain","abbr":"","def":"색 보정 행렬 한 행의 계수 제곱합의 제곱근 √ΣM². 채널 노이즈가 독립일 때 CCM이 노이즈를 몇 배 키우는지 나타내며, 채널 겹침이 클수록 커진다.","chapters":["color"]},
    {"ko":"컬러 PSNR","en":"Color PSNR","abbr":"CPSNR","def":"R·G·B 세 채널의 제곱 오차를 함께 평균해 계산한 PSNR. 디모자이킹 알고리즘 비교에 표준처럼 쓰인다.","chapters":["color"]},
    {"ko":"F-넘버","en":"F-number","abbr":"N","def":"초점 거리 ÷ 입사동 지름. 상면 조도는 1/N²에 비례하고, 한 스톱(√2배)마다 빛이 절반이 된다.","chapters":["optics"]},
    {"ko":"초점 거리","en":"Focal length","abbr":"f","def":"무한 원 물체의 상이 맺히는 거리. 같은 화각이면 센서가 클수록 초점 거리와 렌즈가 커진다.","chapters":["optics"]},
    {"ko":"피사계 심도","en":"Depth of field","abbr":"DOF","def":"초점이 맞은 것으로 보이는 물체 거리 범위. F-넘버가 클수록, 센서가 작을수록(같은 화각·구도 기준) 깊어진다.","chapters":["optics"]},
    {"ko":"광학 포맷","en":"Optical format","abbr":"","def":"센서 크기를 1/2.55\", 1/1.3\", 1\"처럼 인치로 표기하는 관습. 실제 대각은 대략 16 mm × (인치 값)이다. 옛 촬상관 외경에서 유래했다.","chapters":["optics"]},
    {"ko":"이미지 서클","en":"Image circle","abbr":"","def":"렌즈가 쓸 만한 화질로 상을 맺는 원형 영역. 센서 대각보다 커야 모서리가 어두워지거나 흐려지지 않는다.","chapters":["optics"]},
    {"ko":"Airy 디스크","en":"Airy disk","abbr":"","def":"원형 조리개의 회절로 점광원이 만드는 중심 밝은 원. 첫 어두운 고리까지의 지름은 2.44λN으로, F/2·550 nm에서 약 2.7 µm다.","chapters":["optics"]},
    {"ko":"회절 한계","en":"Diffraction limit","abbr":"","def":"수차가 없어도 회절 때문에 도달할 수 없는 해상도 한계. 비간섭 결상의 차단 주파수는 1/(λN)이다.","chapters":["optics"]},
    {"ko":"변조 전달 함수","en":"Modulation transfer function","abbr":"MTF","def":"공간 주파수별로 명암 대비가 얼마나 전달되는지를 나타내는 함수. 렌즈·픽셀 개구·크로스토크 MTF의 곱이 시스템 MTF다.","chapters":["optics"]},
    {"ko":"나이퀴스트 주파수","en":"Nyquist frequency","abbr":"","def":"샘플링 간격 p로 앨리어싱 없이 표현할 수 있는 최대 주파수 1/(2p). 1 µm 픽셀이면 500 lp/mm이다.","chapters":["optics"]},
    {"ko":"주광선각","en":"Chief ray angle","abbr":"CRA","def":"조리개 중심을 지나 상면의 한 점에 도달하는 광선의 각도. 폰 렌즈는 가장자리에서 30°를 넘으므로 마이크로렌즈를 중심 쪽으로 시프트해 맞춘다.","chapters":["optics"]},
    {"ko":"광학 저역 통과 필터","en":"Optical low-pass filter","abbr":"OLPF","def":"복굴절 결정으로 상을 살짝 번지게 해 나이퀴스트 이상의 주파수를 줄이는 필터. 모아레를 줄이지만 선예도가 떨어진다.","chapters":["optics"]},
    {"ko":"주변광량 저하","en":"Vignetting (cos⁴ fall-off)","abbr":"","def":"화면 가장자리로 갈수록 어두워지는 현상. 광학적 가림과 cos⁴θ 법칙, 픽셀의 각도 응답이 원인이며 ISP의 LSC로 보정한다.","chapters":["optics"]},
    {"ko":"순차 광선 추적","en":"Sequential Ray Tracing","abbr":"","def":"렌즈 처방(곡률·원뿔 상수·두께·굴절률)을 따라 광선마다 면과의 교점, 법선, 벡터 스넬 법칙을 순서대로 계산해 상면까지 추적하는 렌즈 해석 방법. 스폿 다이어그램, 왜곡, 상면 만곡을 구한다.","chapters":["optics"]},
    {"ko":"스폿 다이어그램","en":"Spot Diagram","abbr":"","def":"입사동을 고르게 채운 광선들이 상면에 떨어진 점의 분포. 무게중심에 대한 RMS 반경으로 크기를 나타내며, 에어리 디스크보다 작아지면 파동광학 평가(PSF·MTF)가 필요하다.","chapters":["optics"]},
    {"ko":"페츠발 합","en":"Petzval Sum","abbr":"","def":"얇은 렌즈들의 굴절력을 굴절률로 나눈 합 Σφᵢ/nᵢ. 비점수차가 없을 때 상면의 곡률을 정하며 렌즈 굽힘이나 조리개 위치로는 바뀌지 않는다. 떨어진 양·음 렌즈로 줄여 상면을 평탄화한다.","chapters":["optics"]},
    {"ko":"상면 만곡","en":"Field Curvature","abbr":"","def":"축외 상점의 초점이 평면이 아니라 곡면 위에 맺히는 수차. 자오(T)·구결(S) 초점면이 따로 휘며 그 차이가 비점수차다. 평평한 센서에서는 가장자리 초점이 흐려진다.","chapters":["optics"]},
    {"ko":"파면 수차","en":"Wavefront Aberration","abbr":"","def":"출사동에서 이상적인 구면파와 실제 파면 사이의 광로차 W(ρ,θ). 3차 항은 디포커스, 구면수차, 코마, 비점수차로 나뉘며, 동공 함수의 위상이 되어 PSF와 MTF를 결정한다.","chapters":["optics"]},
    {"ko":"동공 함수","en":"Pupil Function","abbr":"","def":"출사동의 투과 진폭과 파면 수차 위상을 합친 복소 함수 P = A·exp(i2πW/λ). 그 푸리에 변환의 제곱이 PSF, 자기상관이 OTF다.","chapters":["optics"]},
    {"ko":"스트렐 비","en":"Strehl Ratio","abbr":"","def":"수차가 있는 PSF의 꼭짓값을 무수차 PSF의 꼭짓값으로 나눈 비. 마레샬 근사로 exp[−(2πσ_W/λ)²]이며, 0.8 이상(σ_W ≤ λ/14)이면 흔히 회절 한계 렌즈로 본다.","chapters":["optics"]},
    {"ko":"단파장 통과 엣지 필터","en":"Short-Pass Edge Filter","abbr":"","def":"고·저굴절 유전체 박막을 1/4 파장 두께로 쌓아 긴 파장을 반사로 막고 짧은 파장을 통과시키는 간섭 필터. 반사형 IR 컷 필터가 대표적이며 입사각이 커지면 엣지가 짧은 파장으로 이동한다.","chapters":["optics"]},
    {"ko":"블루 글라스","en":"Blue Glass (Absorptive IR Filter)","abbr":"","def":"Cu²⁺ 이온을 넣은 인산염 유리로 근적외선을 흡수하는 필터. 엣지가 입사각에 거의 의존하지 않아 간섭형 IR 컷 필터와 조합(하이브리드)해 CRA가 큰 모바일 모듈의 컬러 쉐이딩과 적색 고스트를 줄인다.","chapters":["optics"]},
    {"ko":"4T 능동 픽셀","en":"4T active pixel sensor","abbr":"4T APS","def":"PPD + 전송(TG)·리셋(RST)·소스 팔로워(SF)·행 선택(SEL) 트랜지스터 4개로 된 표준 CMOS 픽셀. 픽셀 안에서 증폭하므로 '능동' 픽셀이다.","chapters":["readout"]},
    {"ko":"전송 게이트","en":"Transfer gate","abbr":"TG","def":"포토다이오드의 전하를 플로팅 디퓨전으로 옮기는 트랜지스터. 완전 전송이 되지 않으면 잔상(lag)이 생긴다.","chapters":["readout"]},
    {"ko":"플로팅 디퓨전","en":"Floating diffusion","abbr":"FD","def":"전송된 전하를 전압으로 바꾸는 작은 커패시턴스 노드. 용량 C_FD가 작을수록 전자 하나당 전압(변환 이득)이 커진다.","chapters":["readout"]},
    {"ko":"소스 팔로워","en":"Source follower","abbr":"SF","def":"FD 전압을 받아 컬럼 라인을 구동하는 픽셀 내 버퍼 증폭기. 이득은 1보다 약간 작고, 읽기 노이즈(1/f, RTS)의 주요 발생원이다.","chapters":["readout"]},
    {"ko":"상관 이중 샘플링","en":"Correlated double sampling","abbr":"CDS","def":"리셋 레벨과 신호 레벨을 차례로 읽어 빼는 기법. kTC 리셋 노이즈와 오프셋, 저주파 노이즈를 제거한다.","chapters":["readout"]},
    {"ko":"kTC 노이즈","en":"kTC (reset) noise","abbr":"","def":"커패시터를 리셋할 때 남는 열 노이즈. 전하 표준편차는 √(kTC)/q로, CDS로 상쇄할 수 있다.","chapters":["readout"]},
    {"ko":"변환 이득","en":"Conversion gain","abbr":"CG","def":"전자 한 개가 만드는 FD 전압 변화 q/C_FD(µV/e⁻). 높으면 읽기 노이즈에 유리하지만 전압 스윙 때문에 담을 수 있는 전자 수가 줄어든다.","chapters":["readout"]},
    {"ko":"아날로그-디지털 변환기","en":"Analog-to-digital converter","abbr":"ADC","def":"픽셀 전압을 디지털 코드로 바꾸는 회로. 비트 수가 b이면 2^b 단계로 양자화된다.","chapters":["readout"]},
    {"ko":"컬럼 병렬 ADC","en":"Column-parallel ADC","abbr":"","def":"열마다 ADC를 하나씩 두어 한 행을 동시에 변환하는 구조. 변환 속도 요구를 행 단위로 낮춰 CMOS 센서의 고속·저노이즈를 가능하게 했다.","chapters":["readout"]},
    {"ko":"단일 기울기 ADC","en":"Single-slope ADC","abbr":"SS-ADC","def":"램프 전압과 입력을 비교하며 카운터를 세는 ADC. 구조가 작아 컬럼 ADC로 널리 쓰이며, 변환 시간은 2^b 클록에 비례한다.","chapters":["readout"]},
    {"ko":"공유 픽셀","en":"Shared pixel architecture","abbr":"","def":"여러 포토다이오드가 하나의 FD·SF·RST를 공유하는 구조. 픽셀당 트랜지스터 수를 줄여 작은 픽셀을 가능하게 하고, FD에서 전하 합산 비닝을 할 수 있다.","chapters":["readout"]},
    {"ko":"아날로그 게인","en":"Analog gain","abbr":"PGA","def":"ADC 앞에서 신호를 증폭하는 것. ADC 이후 노이즈의 입력 환산값을 줄여 저조도 읽기 노이즈를 낮춘다.","chapters":["readout"]},
    {"ko":"고변환 이득 / 저변환 이득","en":"High / low conversion gain","abbr":"HCG / LCG","def":"DCG 픽셀의 두 판독 모드. HCG는 DCG 게이트를 끈 작은 FD 용량으로 읽어 CG가 크고 읽기 노이즈가 작다. LCG는 추가 커패시터를 붙여 CG를 낮추고 풀웰을 늘린다. 두 판독을 합치면 단일 노출에서 DR이 넓어진다.","chapters":["readout"]},
    {"ko":"FD 비선형성","en":"Floating diffusion nonlinearity","abbr":"","def":"FD 용량 중 접합 성분이 역바이어스에 따라 C_j(V) = C_j0/(1+V/φ)^m로 변해, 전자가 들어올수록 CG가 조금씩 줄어드는 압축형 비선형. 전자 수–전압 관계는 ΔV = nq/C가 아니라 C(V)의 적분으로 구한다.","chapters":["readout"]},
    {"ko":"상관 다중 샘플링","en":"Correlated multiple sampling","abbr":"CMS","def":"리셋 레벨과 신호 레벨을 각각 M번 샘플해 평균한 뒤 빼는 판독. 백색(열) 노이즈 분산은 약 1/M로 줄지만, 샘플 구간이 길어져 1/f·RTS 노이즈는 조금밖에 줄지 않고 라인 시간이 늘어난다.","chapters":["readout"]},
    {"ko":"샘플링 전달 함수","en":"Sampling transfer function","abbr":"","def":"샘플 가중치 a_k와 시각 t_k로 정의되는 H(f) = Σ a_k e^(−j2πf t_k). 읽기 노이즈 분산은 노이즈 PSD에 |H|²과 회로 대역폭을 곱해 적분한 값이다. CDS는 |H|² = 4 sin²(πfΔt)로 저주파를 억제한다.","chapters":["readout"]},
    {"ko":"컬럼 라인 정착","en":"Column line settling","abbr":"","def":"선택된 픽셀의 SF가 수 pF의 컬럼 라인 전압을 목표값의 ½ LSB 안으로 끌어오는 과정. 신호 방향(FD 하강)에서는 SF가 꺼져 전류원이 일정 전류로 방전하는 슬루잉 구간이 먼저 오고, 그 뒤 τ = C_col/g_m의 지수 정착이 이어진다. 비트가 하나 늘 때마다 τ·ln2가 더 필요하다.","chapters":["readout"]},
    {"ko":"슬루율","en":"Slew rate","abbr":"SR","def":"회로가 낼 수 있는 최대 전압 변화 속도. 컬럼 라인에서는 SR = I_bias/C_col이며, 큰 신호 스텝의 정착 시간 앞부분을 결정한다.","chapters":["readout"]},
    {"ko":"SAR ADC","en":"Successive-approximation-register ADC","abbr":"SAR","def":"이진 탐색으로 한 비트씩 결정하는 ADC. N비트에 N번의 비교만 필요해 싱글 슬로프보다 빠르지만, 커패시터 DAC가 커서 컬럼 피치에 넣기 어렵고 소자 정합이 선형성을 좌우한다.","chapters":["readout"]},
    {"ko":"사이클릭 ADC","en":"Cyclic (algorithmic) ADC","abbr":"","def":"잔차를 2배로 증폭해 같은 회로에 되먹이며 한 사이클마다 1비트(또는 1.5비트)씩 결정하는 ADC. 회로가 작고 빠르지만 증폭기 이득 오차와 노이즈가 반복마다 누적된다.","chapters":["readout"]},
    {"ko":"2단 싱글 슬로프 ADC","en":"Two-step single-slope ADC","abbr":"","def":"거친 램프로 상위 비트를, 고운 램프로 하위 비트를 정하는 싱글 슬로프 변형. 변환 클록 수가 2^N에서 2^Nc + 2^Nf로 줄어 수십 배 빠르지만, 두 램프 기울기의 정합이 경계 코드의 DNL을 결정한다.","chapters":["readout"]},
    {"ko":"샷 노이즈","en":"Shot noise","abbr":"","def":"광자 도착의 푸아송 통계에서 오는 근본 노이즈. 신호 N 전자일 때 표준편차는 √N이므로 샷 노이즈 한계 SNR = √N이다.","chapters":["noise"]},
    {"ko":"읽기 노이즈","en":"Read noise","abbr":"σ_r","def":"빛이 없을 때도 읽을 때마다 더해지는 노이즈(e⁻ rms). 소스 팔로워, 컬럼 증폭기, ADC 노이즈의 합으로 최신 센서는 1~2 e⁻, 과학용은 1 e⁻ 이하다.","chapters":["noise"]},
    {"ko":"암전류","en":"Dark current","abbr":"","def":"빛 없이 열적으로 생성되는 전자 흐름(e⁻/s). 온도가 6~8 °C 오를 때마다 대략 두 배가 되며, 그 자체의 샷 노이즈도 만든다.","chapters":["noise"]},
    {"ko":"암신호 불균일","en":"Dark signal non-uniformity","abbr":"DSNU","def":"픽셀마다 다른 암전류·오프셋에서 오는 고정 패턴 노이즈. 신호와 무관한 오프셋 형태다.","chapters":["noise"]},
    {"ko":"광응답 불균일","en":"Photo response non-uniformity","abbr":"PRNU","def":"픽셀마다 감도(이득)가 조금씩 다른 데서 오는 고정 패턴 노이즈. 신호에 비례하므로(보통 0.5~1 %) 밝은 영역 SNR의 상한을 만든다.","chapters":["noise"]},
    {"ko":"고정 패턴 노이즈","en":"Fixed pattern noise","abbr":"FPN","def":"프레임마다 같은 위치에 반복되는 공간 노이즈. DSNU·PRNU, 열(column) 단위 오프셋 등이 있으며 보정으로 줄일 수 있다.","chapters":["noise"]},
    {"ko":"RTS 노이즈","en":"Random telegraph signal noise","abbr":"RTS","def":"트랜지스터 게이트 산화막의 결함이 전자를 잡았다 놓으며 신호가 두 레벨 사이를 오가는 노이즈. 소수 픽셀에서 큰 읽기 노이즈 꼬리를 만든다.","chapters":["noise"]},
    {"ko":"신호 대 잡음비","en":"Signal-to-noise ratio","abbr":"SNR","def":"신호 평균을 노이즈 표준편차로 나눈 값. dB로는 20 log₁₀(S/σ). SNR 10(20 dB)은 '쓸 만한' 저조도 화질의 흔한 기준이다.","chapters":["noise"]},
    {"ko":"다이내믹 레인지","en":"Dynamic range","abbr":"DR","def":"측정 가능한 최대 신호와 최소 신호(노이즈 바닥)의 비. 보통 20 log₁₀(FWC/읽기 노이즈) dB로 표기한다.","chapters":["noise"]},
    {"ko":"광자 전달 곡선","en":"Photon transfer curve","abbr":"PTC","def":"평균 신호 대 노이즈(또는 분산)를 로그-로그로 그린 곡선. 읽기 노이즈·샷 노이즈·PRNU 구간과 변환 이득, FWC를 한 번에 추출한다.","chapters":["noise"]},
    {"ko":"EMVA 1288","en":"EMVA 1288 standard","abbr":"EMVA","def":"유럽 머신 비전 협회의 카메라·센서 성능 측정 표준. QE, 읽기 노이즈, DR, DSNU/PRNU를 같은 방법으로 측정해 비교할 수 있게 한다.","chapters":["noise"]},
    {"ko":"ISO 감도","en":"ISO sensitivity / gain","abbr":"ISO","def":"출력 밝기 기준으로 정의한 감도 표기. 센서 입장에서는 대부분 아날로그·디지털 게인 설정이며, 광자 수 자체를 늘리지는 않는다.","chapters":["noise"]},
    {"ko":"양자화 노이즈","en":"Quantization noise","abbr":"","def":"연속 신호를 정수 코드로 반올림하면서 생기는 오차. 1 LSB 폭의 균일 분포이므로 표준편차는 LSB/√12다.","chapters":["noise"]},
    {"ko":"핫 픽셀","en":"Hot pixel","abbr":"","def":"결함으로 암전류가 비정상적으로 큰 픽셀. 긴 노출이나 고온에서 밝은 점으로 보이며 DPC로 보정한다.","chapters":["noise"]},
    {"ko":"노이즈 예산","en":"Noise budget","abbr":"","def":"리드아웃 체인의 각 노이즈 성분을 FD 전자 수로 환산해 분산으로 더한(RSS) 표. 어느 단이 읽기 노이즈를 지배하는지와 CG·게인·비트 수 같은 설계 손잡이의 효과를 보여 준다.","chapters":["noise"]},
    {"ko":"입력 환산 노이즈","en":"Input-referred noise","abbr":"","def":"체인 중간에서 더해진 노이즈를 그 지점까지의 이득으로 나눠 입력(FD 전자 수) 기준으로 나타낸 값. 뒷단 노이즈일수록 앞단 이득으로 많이 나뉜다.","chapters":["noise"]},
    {"ko":"광자 계수","en":"Photon counting (photon-number resolving)","abbr":"","def":"읽기 노이즈가 약 0.3 e⁻ 이하로 작아 판독값 히스토그램이 정수 전자 위치의 봉우리로 갈라질 때, 판독값을 반올림해 전자 수를 직접 세는 방식. 오류율은 Q(1/2σ_r)에 비례해 지수적으로 줄어든다.","chapters":["noise"]},
    {"ko":"쿼터 이미지 센서","en":"Quanta Image Sensor","abbr":"QIS","def":"광전자 하나를 구분할 만큼 노이즈가 작은 아주 작은 픽셀(jot)을 고속으로 여러 번 읽어 비트 평면을 합산하는 센서 개념. 1비트형은 1의 비율 p로부터 λ = −ln(1 − p)로 노출을 복원한다.","chapters":["noise"]},
    {"ko":"딥 서브전자 읽기 노이즈","en":"Deep sub-electron read noise","abbr":"DSERN","def":"광자 계수가 가능한 수준(대략 0.3 e⁻ rms 이하)의 읽기 노이즈. 높은 CG, 큰 SF 게이트 면적, 다중 샘플링, 충분한 아날로그 게인이 함께 필요하다.","chapters":["noise"]},
    {"ko":"노이즈 파워 스펙트럼","en":"Noise power spectrum","abbr":"NPS","def":"평균을 뺀 영상의 2-D 푸리에 변환 크기 제곱을 픽셀 수로 나눈 것. 전체 평균이 분산과 같고(파스발), 컬럼 FPN은 k_y = 0 선, 행 노이즈는 k_x = 0 선, 주기적 간섭은 점 쌍으로 드러난다.","chapters":["noise"]},
    {"ko":"색 노이즈","en":"Chroma noise","abbr":"","def":"색차(Cb, Cr) 성분의 노이즈로 보이는 알록달록한 얼룩. WB 이득과 음수 계수를 가진 CCM이 채널 노이즈를 증폭·혼합해 휘도 노이즈보다 크게 만든다. 색차 채널만 강하게 평활화해 줄인다.","chapters":["noise","isp"]},
    {"ko":"노이즈 공분산 전파","en":"Noise covariance propagation","abbr":"","def":"선형 변환 y = Mx를 지난 노이즈의 공분산이 Σ_y = MΣ_xMᵀ가 되는 성질. ISP의 WB·CCM 단계 노이즈를 정확히 계산할 수 있다.","chapters":["noise"]},
    {"ko":"선형성 오차","en":"Linearity error","abbr":"LE","def":"응답 곡선이 최소자승 직선에서 벗어난 정도(%). EMVA 1288은 포화의 5~95 % 구간에서 편차의 (최대−최소)/2로 정의한다.","chapters":["characterization"]},
    {"ko":"선형 풀웰","en":"Linear full well capacity","abbr":"","def":"응답이 직선에서 정해진 기준(1~5 %) 이상 벗어나기 직전의 신호. 포화 풀웰보다 작으며 정량 측정과 HDR 합성의 실제 상한이다.","chapters":["characterization"]},
    {"ko":"배증 온도","en":"Doubling temperature","abbr":"","def":"암전류가 두 배가 되는 온도 간격. ΔT ≈ kT²ln2/Ea로, 300 K에서 확산 성분 약 5 K, 생성 성분 약 10 K다.","chapters":["characterization"]},
    {"ko":"활성화 에너지","en":"Activation energy","abbr":"Ea","def":"암전류의 온도 의존성을 정하는 에너지. 확산 전류는 약 1.1 eV, 결함에 의한 생성 전류는 약 0.56 eV다.","chapters":["characterization"]},
    {"ko":"이미지 래그","en":"Image lag","abbr":"","def":"전송되지 못하고 PD에 남은 전하가 다음 프레임에 나오는 잔상. 밝은 프레임 직후 암 프레임의 잔류 신호 비율(%)로 잰다.","chapters":["characterization"]},
    {"ko":"행 노이즈","en":"Temporal row noise","abbr":"","def":"한 행이 같은 순간에 샘플링되어 전원·기준 전압의 흔들림이 행 전체에 더해지는 노이즈. 줄무늬라 눈에 잘 띄어 픽셀 노이즈의 1/10 이하로 억제해야 한다.","chapters":["characterization"]},
    {"ko":"블랙 선","en":"Black sun / eclipse","abbr":"","def":"극단적으로 밝은 곳이 검게 나오는 현상. 리셋 레벨 샘플링 순간 FD 전압이 빛에 끌려 내려가 CDS 차가 줄어든다.","chapters":["characterization"]},
    {"ko":"에탈로닝","en":"Etaloning / fringing","abbr":"","def":"얇은 BSI 실리콘에서 근적외선이 위아래 면 사이를 왕복하며 간섭해 QE가 파장·위치에 따라 출렁이는 현상. 주기 Δλ ≈ λ²/(2nd).","chapters":["characterization"]},
    {"ko":"경사 에지법","en":"Slanted-edge method","abbr":"","def":"약 5° 기울인 에지 영상에서 초해상 에지 응답을 만들어 MTF를 구하는 측정법.","chapters":["characterization"]},
    {"ko":"SNR10","en":"SNR10","abbr":"","def":"정해진 렌즈·노출 조건에서 색 처리 후 휘도 SNR이 10이 되는 장면 조도(lux). 작을수록 저조도 성능이 좋다.","chapters":["characterization"]},
    {"ko":"기준 포토다이오드","en":"Reference photodiode","abbr":"","def":"표준 기관에 교정을 추적할 수 있는 광검출기. 센서 위치의 복사 조도(W/m²)를 재서 픽셀에 도달한 광자 수를 알게 해 주므로, QE와 EMVA 1288 감도 측정의 기준이 된다.","chapters":["characterization"]},
    {"ko":"단색광기","en":"Monochromator","abbr":"","def":"회절 격자와 출구 슬릿으로 백색광에서 좁은 파장 대역만 골라내는 장치. 파장을 주사하며 센서와 기준 포토다이오드의 신호를 비교해 분광 QE를 얻는다.","chapters":["characterization"]},
    {"ko":"슬릿 함수","en":"Slit function","abbr":"","def":"단색광기 출력의 파장 분포로, 보통 반치폭 Δλ의 삼각형이다. 측정된 QE는 참 QE와 슬릿 함수의 합성곱이므로 Δλ가 에탈로닝 주기에 가까우면 잔물결이 뭉개진다.","chapters":["characterization"]},
    {"ko":"차수 분리 필터","en":"Order-sorting filter","abbr":"","def":"격자의 2차 회절로 λ/2 빛이 λ 위치에 섞여 들어오는 것을 막는 장파장 통과 필터. 빼먹으면 근적외선 QE가 실제보다 높게 측정된다.","chapters":["characterization"]},
    {"ko":"아레니우스 그림","en":"Arrhenius plot","abbr":"","def":"ln(암전류)를 1/kT에 대해 그린 그래프. 기울기가 활성화 에너지이며, 두 직선의 합으로 맞추면 고온의 확산 성분(E_a≈E_g)과 저온의 생성 성분(E_a≈E_g/2)을 가를 수 있다.","chapters":["characterization"]},
    {"ko":"확산 암전류","en":"Diffusion dark current","abbr":"","def":"중성 영역의 열생성 소수 캐리어가 공핍층으로 확산해 들어오는 암전류 성분. n_i²에 비례해 활성화 에너지가 밴드갭(약 1.1 eV)에 가깝고 고온에서 지배적이다.","chapters":["characterization"]},
    {"ko":"생성 암전류","en":"Generation dark current","abbr":"","def":"공핍층과 계면의 밴드갭 중간 결함(SRH 중심)이 전자-정공 쌍을 만드는 암전류 성분. n_i에 비례해 활성화 에너지가 약 E_g/2이고 상온 부근에서 지배적이다.","chapters":["characterization"]},
    {"ko":"시스템 이득","en":"System gain","abbr":"K","def":"전자 1개가 만드는 디지털 출력(DN/e⁻). EMVA 1288에서는 광자 전달 곡선의 기울기(시간 노이즈 분산 대 평균 신호)로 구하며, 모든 e⁻ 단위 결과의 환산 기준이다.","chapters":["characterization"]},
    {"ko":"포화 용량","en":"Saturation capacity","abbr":"μ_e.sat","def":"EMVA 1288에서 시간 노이즈 분산이 최대가 되는 지점의 신호를 전자 수로 환산한 값. 데이터시트의 ‘풀웰’과 달리 ADC 클리핑이나 FD 스윙 한계까지 포함한 실측 상한이다.","chapters":["characterization"]},
    {"ko":"절대 감도 문턱","en":"Absolute sensitivity threshold","abbr":"μ_p.min","def":"SNR = 1이 되는 최소 입사 광자 수. 암 노이즈 σ_d와 QE η로 대략 (σ_d/η)이며, EMVA 1288 보고서에서 저조도 성능을 하나의 숫자로 비교할 때 쓴다.","chapters":["characterization"]},
    {"ko":"롤링 셔터","en":"Rolling shutter","abbr":"RS","def":"행마다 조금씩 시간 차를 두고 노출·읽기를 하는 방식. 구조가 간단하고 노이즈가 낮지만 빠른 움직임에서 기울어짐(skew)과 젤로 현상이 생긴다.","chapters":["shutter"]},
    {"ko":"글로벌 셔터","en":"Global shutter","abbr":"GS","def":"모든 픽셀이 동시에 노출을 시작·종료하는 방식. 픽셀 안에 전하나 전압을 잠시 저장할 메모리 노드가 필요하다.","chapters":["shutter"]},
    {"ko":"기생 광 감도","en":"Parasitic light sensitivity","abbr":"PLS","def":"글로벌 셔터 픽셀의 저장 노드가 읽기를 기다리는 동안 새어 들어온 빛에 반응하는 정도. 저장 노드 차광 성능 지표다.","chapters":["shutter"]},
    {"ko":"젤로 효과","en":"Jello effect / skew","abbr":"","def":"롤링 셔터의 행별 시간 차 때문에 움직이는 물체나 흔들리는 카메라 영상이 기울거나 출렁이는 왜곡.","chapters":["shutter"]},
    {"ko":"플리커","en":"Flicker","abbr":"LFM","def":"교류 조명(100/120 Hz)이나 PWM LED의 깜빡임이 노출과 맞물려 줄무늬·깜빡임으로 찍히는 현상. 차량용에서는 LED 신호등 인식을 위한 LFM(LED flicker mitigation)이 필수다.","chapters":["shutter"]},
    {"ko":"고 다이내믹 레인지","en":"High dynamic range","abbr":"HDR","def":"단일 노출의 DR 한계를 넘어 밝은 곳과 어두운 곳을 함께 담는 기법. 다중 노출, DCG, LOFIC, 분할 픽셀 등이 있다.","chapters":["shutter"]},
    {"ko":"이중 변환 이득","en":"Dual conversion gain","abbr":"DCG","def":"FD에 추가 커패시터를 스위치로 붙였다 떼어 높은 CG(저노이즈)와 낮은 CG(큰 용량)를 모두 쓰는 픽셀. 두 신호를 합쳐 한 노출에서 HDR을 얻는다.","chapters":["shutter"]},
    {"ko":"횡방향 오버플로 커패시터","en":"Lateral overflow integration capacitor","abbr":"LOFIC","def":"포토다이오드가 넘친 전하를 픽셀 안의 큰 커패시터에 따로 모으는 구조. 단일 노출로 120 dB 이상을 얻어 차량용에 쓰인다.","chapters":["shutter"]},
    {"ko":"DOL-HDR","en":"Digital overlap HDR","abbr":"DOL","def":"한 프레임 안에서 긴 노출과 짧은 노출 행을 시간차로 번갈아 읽어 합성하는 다중 노출 HDR. 움직임이 있으면 합성 아티팩트가 생길 수 있다.","chapters":["shutter"]},
    {"ko":"라인 타임","en":"Line time","abbr":"1H","def":"한 행을 읽는 데 걸리는 시간. 프레임 시간 ≈ 라인 타임 × (행 수 + 블랭킹)이며, 롤링 셔터 왜곡의 크기를 정한다.","chapters":["shutter"]},
    {"ko":"프레임률","en":"Frame rate","abbr":"fps","def":"초당 출력 프레임 수. 행 수, 라인 타임, ADC 비트 수, 인터페이스 대역폭이 상한을 정한다.","chapters":["shutter"]},
    {"ko":"마차 바퀴 효과","en":"Wagon-wheel (stroboscopic) effect","abbr":"","def":"회전체의 프레임당 회전각이 날개 간격의 정수배에 가까우면 멈추거나 천천히·거꾸로 도는 것처럼 보이는 시간 샘플링 에일리어싱. 글로벌 셔터로도 없어지지 않는다.","chapters":["shutter"]},
    {"ko":"메모리 노드","en":"Memory (storage) node","abbr":"MN","def":"전하 영역 글로벌 셔터 픽셀에서 노출이 끝난 전하를 판독 차례까지 보관하는 차광된 접합. 대기 시간에 비례해 PLS와 암전류 오차가 쌓인다.","chapters":["shutter"]},
    {"ko":"전압 영역 글로벌 셔터","en":"Voltage-domain global shutter","abbr":"","def":"리셋·신호 전압을 픽셀 안 커패시터 두 개에 샘플링해 보관하는 GS 방식. PLS에는 강하지만 두 샘플의 kTC 노이즈 √(2kT/C)를 CDS로 지울 수 없고 커패시터 누설이 생긴다.","chapters":["shutter"]},
    {"ko":"분할 픽셀","en":"Split pixel","abbr":"","def":"한 픽셀 안에 감도가 다른 큰 PD와 작은 PD를 두어 동시에 노출하는 단일 노출 HDR 구조. 감도 비 k에 대해 전환점 SNR 딥이 약 10·log10(k) dB다.","chapters":["shutter"]},
    {"ko":"SNR 딥","en":"SNR dip","abbr":"","def":"HDR 합성에서 고감도 경로에서 저감도 경로로 넘어가는 전환점에 SNR이 갑자기 떨어지는 현상. 다중 노출과 분할 픽셀에서 크고, 같은 전하를 읽는 DCG에서는 작다.","chapters":["shutter"]},
    {"ko":"라인 버퍼","en":"Line buffer","abbr":"","def":"스태거드(DOL) HDR에서 늦게 출력되는 짧은 노출 행이 도착할 때까지 긴 노출 행을 보관하는 메모리. 필요한 행 수는 ⌈t_S / t_row⌉이다.","chapters":["shutter"]},
    {"ko":"로컬 톤 매핑","en":"Local tone mapping","abbr":"","def":"로그 휘도를 기저와 디테일로 나눠 기저만 압축하는 등 위치마다 다른 톤 곡선을 쓰는 톤 매핑. 하이라이트·그림자의 국소 대비를 살린다.","chapters":["shutter"]},
    {"ko":"헤일로","en":"Halo artifact","abbr":"","def":"로컬 톤 매핑에서 기저 추정이 밝은 에지를 넘어 번져, 압축 후 에지 둘레에 어둡거나 밝은 테가 생기는 아티팩트. 에지 보존 필터로 줄인다.","chapters":["shutter"]},
    {"ko":"가이디드 필터","en":"Guided filter","abbr":"","def":"국소 선형 모델로 에지를 보존하며 평활하는 필터(He et al.). 박스 필터만으로 O(N)에 계산돼 톤 매핑 기저층·노이즈 저감에 쓰인다.","chapters":["shutter"]},
    {"ko":"필믹 톤 커브","en":"Filmic tone curve","abbr":"","def":"필름의 S자 특성을 흉내 낸 전역 톤 곡선(예: ACES 근사). 어두운 쪽 토(toe)와 밝은 쪽 숄더(shoulder)로 대비와 하이라이트 롤오프를 함께 준다.","chapters":["shutter"]},
    {"ko":"이미지 신호 처리기","en":"Image signal processor","abbr":"ISP","def":"RAW 데이터를 사람이 보는 영상으로 바꾸는 처리 파이프라인(하드웨어). 블랙 레벨→결함 보정→셰이딩→디모자이크→WB→CCM→감마→NR·샤프닝 순이 전형적이다.","chapters":["isp"]},
    {"ko":"RAW 이미지","en":"RAW image","abbr":"RAW","def":"ISP 처리 전 센서 출력. 픽셀마다 CFA 한 색의 선형 값만 있으며 보통 10~14비트다.","chapters":["isp"]},
    {"ko":"블랙 레벨 보정","en":"Black level correction","abbr":"BLC","def":"노이즈가 잘리지 않도록 일부러 더해 둔 오프셋(pedestal)과 암신호를 빼는 단계. 광학 블랙(OB) 픽셀 값을 기준으로 한다.","chapters":["isp"]},
    {"ko":"결함 픽셀 보정","en":"Defect pixel correction","abbr":"DPC","def":"핫·데드 픽셀을 찾아 주변 같은 색 픽셀 값으로 대체하는 처리. 공장 보정 목록(static)과 실시간 검출(dynamic)을 함께 쓴다.","chapters":["isp"]},
    {"ko":"렌즈 셰이딩 보정","en":"Lens shading correction","abbr":"LSC","def":"주변광량 저하와 채널별 색 셰이딩을 위치별 이득 맵으로 보정하는 단계. 가장자리 이득이 커져 노이즈도 함께 증폭된다.","chapters":["isp"]},
    {"ko":"자동 화이트 밸런스","en":"Auto white balance","abbr":"AWB","def":"조명의 색을 추정해 흰 물체가 흰색으로 보이도록 R·B 채널 이득을 맞추는 처리.","chapters":["isp"]},
    {"ko":"색 보정 행렬","en":"Color correction matrix","abbr":"CCM","def":"센서 RGB를 표준 색공간(sRGB 등)으로 바꾸는 3×3 행렬. 분광 감도 차이를 보정하지만 비대각 성분이 크면 노이즈가 증폭된다.","chapters":["isp"]},
    {"ko":"감마 보정","en":"Gamma correction","abbr":"","def":"선형 신호를 사람의 밝기 지각과 디스플레이 특성에 맞게 비선형(약 1/2.2 거듭제곱) 변환하는 단계. 어두운 영역에 더 많은 코드를 배분한다.","chapters":["isp"]},
    {"ko":"톤 매핑","en":"Tone mapping","abbr":"","def":"HDR 영상의 넓은 밝기 범위를 표시 장치의 좁은 범위로 압축하는 처리. 전역(global)과 국소(local) 방식이 있다.","chapters":["isp"]},
    {"ko":"3A","en":"Auto exposure / focus / white balance","abbr":"AE·AF·AWB","def":"자동 노출, 자동 초점, 자동 화이트 밸런스를 묶어 부르는 말. 센서 통계를 받아 매 프레임 노출·렌즈·이득을 조절하는 제어 루프다.","chapters":["isp"]},
    {"ko":"노이즈 저감","en":"Noise reduction","abbr":"NR","def":"공간·시간 필터로 노이즈를 줄이는 처리. 디테일 손실(뭉개짐)과의 균형이 핵심이며 최근에는 다중 프레임 합성과 신경망을 쓴다.","chapters":["isp"]},
    {"ko":"클러스터 결함","en":"Cluster defect","abbr":"","def":"인접한 같은 색 픽셀 두 개 이상이 함께 결함인 경우. 서로가 이웃 최댓값(최솟값)이 되어 단순 최대·최소 범위 DPC를 통과하므로, 두 번째 순위 이웃이나 중앙값과 비교해 검출한다.","chapters":["isp"]},
    {"ko":"교차 채널 검사","en":"Cross-channel check","abbr":"","def":"결함 후보 픽셀 바로 옆의 다른 색 픽셀이 같은 방향으로 함께 움직였는지 보는 DPC 단계. 렌즈 PSF 때문에 진짜 광점(별, 하이라이트)은 이웃까지 들어 올리지만 결함은 한 픽셀뿐이라는 점을 이용한다.","chapters":["isp"]},
    {"ko":"격자 게인 맵","en":"Grid gain map (mesh shading table)","abbr":"","def":"영상을 17×13 같은 셀로 나눠 셀마다 플랫 필드 평균의 역수를 노드 게인으로 저장하고 쌍선형 보간하는 LSC 방식. 비대칭 쉐이딩을 따라가지만 셀 노이즈와 테두리 외삽 오차를 안는다.","chapters":["isp"]},
    {"ko":"색 쉐이딩","en":"Color shading","abbr":"","def":"화면 주변부로 갈수록 채널마다 감도가 다르게 떨어져 R/G, B/G 비가 바뀌는 현상. 주광선각(CRA) 불일치와 IR 필터의 각도 의존성이 원인이며, 밝기 쉐이딩과 달리 끝까지 보정해야 얼룩이 보이지 않는다.","chapters":["isp"]},
    {"ko":"shades-of-gray","en":"Shades of gray","abbr":"SoG","def":"채널별 민코프스키 p-평균 (Σf^p/N)^(1/p)을 조명 추정치로 쓰는 AWB. p = 1이면 그레이 월드, p → ∞면 max-RGB이며 p ≈ 6 부근이 평균적으로 좋다.","chapters":["isp"]},
    {"ko":"그레이 엣지","en":"Gray edge","abbr":"","def":"영상 기울기 크기의 민코프스키 평균을 조명으로 보는 AWB. '물체 경계의 색 차이는 평균적으로 무채색'이라는 가정이라 넓은 단색 면에 덜 휘둘린다.","chapters":["isp"]},
    {"ko":"각도 오차","en":"Angular error","abbr":"","def":"참 조명과 추정 조명의 RGB 벡터 사이 각도 θ = arccos(e·ê/|e||ê|). 밝기와 무관하게 색 방향만 비교하는 AWB 표준 지표로, 대략 3° 이상이면 색 틀어짐이 눈에 띈다.","chapters":["isp"]},
    {"ko":"비국소 평균","en":"Non-local means","abbr":"NLM","def":"주변 패치 모양이 닮은 픽셀끼리 가중 평균하는 노이즈 저감. 멀리 떨어져 있어도 같은 구조면 평균하므로 반복 질감과 에지를 잘 지키지만 계산량이 크고, 노이즈가 매우 크면 패치 비교가 흔들린다.","chapters":["isp"]},
    {"ko":"제거된 성분","en":"Method noise","abbr":"","def":"입력에서 NR 출력을 뺀 영상. 이상적인 NR이라면 구조 없는 노이즈만 보여야 하며, 에지나 질감 모양이 보이면 디테일을 함께 지운 것이다.","chapters":["isp"]},
    {"ko":"위상차 AF","en":"Phase-detection autofocus","abbr":"PDAF","def":"렌즈 좌우(또는 상하) 반쪽을 통과한 빛의 상 차이로 초점 방향과 거리를 한 번에 구하는 AF. 차광 픽셀, 듀얼 픽셀, 2×2 OCL 방식이 있다.","chapters":["advanced"]},
    {"ko":"듀얼 픽셀","en":"Dual pixel","abbr":"2PD","def":"한 마이크로렌즈 아래 포토다이오드를 좌우 둘로 나눈 픽셀. 모든 픽셀이 PDAF에 참여하고, 합치면 일반 픽셀처럼 영상을 만든다.","chapters":["advanced"]},
    {"ko":"리모자이크","en":"Remosaic","abbr":"","def":"쿼드·노나 배열의 RAW를 일반 베이어 배열로 재배치·보간하는 처리. 밝은 장면에서 풀해상도를 얻기 위해 쓴다.","chapters":["advanced"]},
    {"ko":"비닝","en":"Binning","abbr":"","def":"인접한 같은 색 픽셀 여러 개의 신호를 합쳐 하나로 출력하는 것. k×k 비닝은 해상도를 1/k²로 줄이는 대신 SNR을 약 k배 높이고 프레임률을 올린다.","chapters":["advanced"]},
    {"ko":"노나셀","en":"Nonacell","abbr":"","def":"같은 색 3×3 픽셀을 한 묶음으로 한 CFA. 108 MP급 초고화소 센서에서 9-in-1 비닝으로 저조도 성능을 확보한다.","chapters":["advanced"]},
    {"ko":"적층 센서","en":"Stacked sensor","abbr":"","def":"픽셀 웨이퍼와 로직(ADC·ISP·메모리) 웨이퍼를 따로 만들어 위아래로 붙인 센서. 각 층에 최적 공정을 쓰고 다이 면적을 줄인다. 3층(DRAM 포함) 구조도 있다.","chapters":["advanced"]},
    {"ko":"하이브리드 본딩","en":"Hybrid bonding (Cu–Cu)","abbr":"","def":"두 웨이퍼의 구리 패드와 산화막을 동시에 직접 접합하는 기술. 수 µm 피치의 초고밀도 연결로 픽셀 단위 적층(픽셀 병렬 ADC)을 가능하게 한다.","chapters":["advanced"]},
    {"ko":"실리콘 관통 전극","en":"Through-silicon via","abbr":"TSV","def":"실리콘 기판을 수직으로 관통하는 전극. 초기 적층 센서에서 두 웨이퍼를 주변부에서 연결하는 데 썼다.","chapters":["advanced"]},
    {"ko":"단일 광자 애벌런치 다이오드","en":"Single-photon avalanche diode","abbr":"SPAD","def":"항복 전압 이상으로 바이어스해 광자 하나로도 애벌런치 전류 펄스를 만드는 다이오드. 광자 도착 시각을 ps 단위로 잴 수 있다.","chapters":["advanced"]},
    {"ko":"직접 ToF","en":"Direct time-of-flight","abbr":"dToF","def":"레이저 펄스가 돌아오는 시간을 직접 측정해 거리를 구하는 방식(d = ct/2). SPAD와 TDC, 히스토그램 처리로 라이다(LiDAR)에 쓰인다.","chapters":["advanced"]},
    {"ko":"간접 ToF","en":"Indirect time-of-flight","abbr":"iToF","def":"변조된 빛의 위상 지연을 여러 탭(tap)의 전하 비로 측정해 거리를 구하는 방식. 해상도가 높지만 최대 거리는 변조 주파수에 따른 모호성이 있다.","chapters":["advanced"]},
    {"ko":"이벤트 센서","en":"Event-based vision sensor","abbr":"DVS / EVS","def":"프레임 대신 각 픽셀의 로그 밝기 변화가 문턱을 넘을 때만 비동기 이벤트를 내는 센서. µs 시간 분해능, 120 dB 이상 DR, 낮은 데이터율이 장점이다.","chapters":["advanced"]},
    {"ko":"단파 적외선","en":"Short-wave infrared","abbr":"SWIR","def":"약 1~2.5 µm 파장 대역. 실리콘은 흡수하지 못하므로 InGaAs, Ge, 양자점(QD) 등의 광흡수층을 쓴다.","chapters":["advanced"]},
    {"ko":"컬러 라우터","en":"Color router","abbr":"","def":"픽셀 위 나노 구조로 색별 빛의 진행 방향을 바꿔 제 색 픽셀로 보내는 소자. 흡수형 CF의 1/3 한계를 넘을 수 있으며, 2025년 양산 모바일 센서(삼성 ISOCELL JNP, 나노프리즘)에 처음 쓰였다.","chapters":["advanced","nanophotonics"]},
    {"ko":"펄스 폭 변조","en":"Pulse width modulation","abbr":"PWM","def":"LED를 빠르게 켜고 끄며 켜진 시간 비율(듀티)로 밝기를 조절하는 방식. 꺼진 구간이 있어 짧은 노출의 카메라에 꺼진 것으로 찍힐 수 있다.","chapters":["automotive"]},
    {"ko":"듀티","en":"Duty cycle","abbr":"D","def":"PWM 한 주기 중 켜져 있는 시간의 비율. 낮을수록 짧은 노출이 꺼진 구간에 걸릴 확률이 커진다.","chapters":["automotive"]},
    {"ko":"분할 노출","en":"Chopped exposure","abbr":"","def":"한 PWM 주기 이상에 걸쳐 짧은 노출 조각을 흩어 누적하는 LFM 기법. 포화 없이 LED의 여러 위상을 표본으로 얻지만 움직이는 물체가 끊겨 보일 수 있다.","chapters":["automotive"]},
    {"ko":"전환점 SNR 딥","en":"SNR drop at transition","abbr":"","def":"다중 신호 HDR에서 한 신호가 포화해 감도가 낮은 다음 신호로 넘어갈 때 SNR이 급락하는 현상. 차량용 센서는 전환점 최소 SNR을 사양으로 관리한다.","chapters":["automotive"]},
    {"ko":"운전자 모니터링 시스템","en":"Driver monitoring system","abbr":"DMS","def":"실내 NIR 카메라로 시선·눈꺼풀·고개를 추적해 졸음과 부주의를 판단하는 시스템. 940 nm 펄스 조명과 글로벌 셔터를 쓴다.","chapters":["automotive"]},
    {"ko":"첨단 운전자 보조 시스템","en":"Advanced driver assistance systems","abbr":"ADAS","def":"전방 카메라 등으로 차선·차량·보행자·신호를 인식해 제동과 조향을 보조하는 기능의 총칭.","chapters":["automotive"]},
    {"ko":"단일점 고장 지표","en":"Single-point fault metric","abbr":"SPFM","def":"위험한 단일 고장 중 안전 메커니즘이 검출·제어하는 비율. ASIL B는 90 %, C는 97 %, D는 99 % 이상을 요구한다.","chapters":["automotive"]},
    {"ko":"RYYCy 필터","en":"Red-Yellow-Yellow-Cyan CFA","abbr":"RYYCy","def":"녹색·청색 대신 투과 대역이 넓은 노랑·청록을 쓴 CFA. 감도를 높이면서 세 채널 색 분리를 유지하지만 색 보정 시 노이즈가 증폭된다.","chapters":["automotive"]},
    {"ko":"접합 온도","en":"Junction temperature","abbr":"Tj","def":"칩 내부 반도체 접합의 실제 온도. 주위 온도에 자체 발열이 더해지며 차량용 센서는 약 125 °C까지 동작을 보장한다.","chapters":["automotive"]},
    {"ko":"전하 전송 효율","en":"Charge transfer efficiency","abbr":"CTE","def":"CCD에서 한 번 전송할 때 다음 우물로 넘어가는 전하의 비율. 1−CTE가 CTI이며 N번 전송 후 (1−CTI)^N만 남는다.","chapters":["space"]},
    {"ko":"전하 트레일","en":"Charge trail","abbr":"","def":"트랩이 붙잡았던 전자를 뒤 픽셀에 놓아 별상이 증폭기 반대쪽으로 꼬리를 끄는 현상. 측광 손실과 중심 이동을 일으킨다.","chapters":["space"]},
    {"ko":"변위 손상","en":"Displacement damage","abbr":"DD","def":"양성자·중성자가 실리콘 원자를 격자에서 튕겨 내 벌크 트랩을 만드는 방사선 손상. CTE 열화와 핫 픽셀의 원인이다.","chapters":["space"]},
    {"ko":"전리 손상","en":"Total ionizing dose","abbr":"TID","def":"방사선이 산화막에 전하를 가두고 계면 상태를 늘리는 손상. 문턱 전압 이동과 표면 암전류 증가로 나타난다.","chapters":["space"]},
    {"ko":"딥 디플리션 CCD","en":"Deep-depletion CCD","abbr":"","def":"두꺼운 고저항 실리콘을 완전 공핍시킨 CCD. 근적외선 QE가 높고 프린징이 적다.","chapters":["space"]},
    {"ko":"수은 카드뮴 텔루라이드","en":"Mercury cadmium telluride","abbr":"HgCdTe","def":"Cd 조성으로 밴드갭과 차단 파장을 조절하는 적외선 검출 재료. 인듐 범프로 Si ROIC에 접합해 쓴다.","chapters":["space"]},
    {"ko":"Up-the-ramp 샘플링","en":"Up-the-ramp sampling","abbr":"UTR","def":"비파괴 판독으로 노출 중 N번 읽고 누적 신호의 기울기를 피팅하는 방식. 읽기 노이즈가 약 √(12/N)배로 줄고 우주선 히트를 계단으로 검출한다.","chapters":["space"]},
    {"ko":"시간 지연 적분","en":"Time delay and integration","abbr":"TDI","def":"상의 이동 속도에 맞춰 전하를 옮기며 N단에 걸쳐 적분하는 스캔 방식. 읽기는 한 번이라 SNR이 √N 이상 좋아진다.","chapters":["space"]},
    {"ko":"전자 증배 CCD","en":"Electron-multiplying CCD","abbr":"EMCCD","def":"증배 레지스터의 충돌 이온화로 읽기 전에 신호를 수백 배 키우는 CCD. 읽기 노이즈는 사실상 사라지지만 과잉 잡음 √2가 붙는다.","chapters":["space"]},
    {"ko":"CCD 방정식","en":"CCD Equation","abbr":"","def":"구경 측광의 SNR을 별 신호, 하늘 배경, 암전류, 읽기 노이즈, 하늘 추정 오차 항으로 나눠 쓴 식. SNR = S / √(S + n_pix(1 + n_pix/n_sky)(B + D + σ_r²)).","chapters":["space"]},
    {"ko":"영점","en":"Photometric Zero Point","abbr":"ZP","def":"검출기에서 1 e⁻/s를 주는 천체의 등급. 망원경 면적, 투과율, 필터, QE를 한 숫자로 묶어 등급을 광전자 유입률로 바꾼다.","chapters":["space"]},
    {"ko":"구경 측광","en":"Aperture Photometry","abbr":"","def":"별 주위 원형 구경 안의 픽셀 값을 더하고 바깥 고리에서 잰 하늘 평균을 빼 별의 밝기를 재는 방법. 배경 한계에서는 반지름 약 0.7 FWHM이 최적이다.","chapters":["space"]},
    {"ko":"시상","en":"Seeing","abbr":"","def":"대기 난류 때문에 지상 망원경의 별상이 퍼지는 정도. 보통 별상의 FWHM(각초)으로 나타낸다.","chapters":["space"]},
    {"ko":"한계 등급","en":"Limiting Magnitude","abbr":"","def":"주어진 노출과 조건에서 정해진 SNR(예: 5σ)로 검출할 수 있는 가장 어두운 천체의 등급.","chapters":["space"]},
    {"ko":"시그마 클리핑","en":"Sigma Clipping","abbr":"","def":"여러 장의 값 중 기준(중앙값)에서 노이즈 모델의 k배 이상 벗어난 값을 버리고 나머지를 평균하는 결합 방법. 우주선 제거에 쓴다.","chapters":["space"]},
    {"ko":"Rule 07","en":"Rule 07","abbr":"","def":"HgCdTe 광다이오드의 암전류 밀도를 차단 파장과 온도의 함수로 요약한 경험식(Tennant, 2007). J = 8367·exp(−1.162·1.24q/(kλT)) A/cm².","chapters":["space"]},
    {"ko":"클록 유도 전하","en":"Clock-Induced Charge","abbr":"CIC","def":"CCD 전송 클록이 바뀔 때 충돌 이온화로 생기는 가짜 전자. EMCCD 광자 계수 모드에서 바닥 노이즈가 된다.","chapters":["space"]},
    {"ko":"동시 도착 손실","en":"Coincidence Loss","abbr":"","def":"광자 계수 검출기에서 한 프레임(또는 시간 창)에 둘 이상 들어온 광자를 하나로 세어 생기는 손실. 계수율이 높을수록 커진다.","chapters":["space"]},
    {"ko":"지상 표본 거리","en":"Ground Sample Distance","abbr":"GSD","def":"지구 관측 영상에서 픽셀 하나가 지표에서 차지하는 거리. 픽셀 피치 × 고도 / 초점 거리.","chapters":["space"]},
    {"ko":"MIPI CSI-2","en":"Camera Serial Interface 2","abbr":"CSI-2","def":"모바일 카메라의 표준 영상 전송 프로토콜. 물리층으로 D-PHY(레인당 수 Gbps) 또는 C-PHY(3선 트리오)를 쓴다.","chapters":["design"]},
    {"ko":"데이터율","en":"Data rate","abbr":"","def":"센서가 초당 내보내는 비트 수 ≈ 화소 수 × 비트 수 × fps(+ 오버헤드). 50 MP·10비트·30 fps면 약 15 Gbps다.","chapters":["design"]},
    {"ko":"회절 한계 조리개","en":"Diffraction-limited aperture","abbr":"DLA","def":"Airy 디스크가 픽셀 약 2개 폭이 되는 F-넘버(≈ 2p/(2.44λ)). 이보다 조리개를 조이면 픽셀을 줄여도 해상도가 늘지 않는다.","chapters":["design"]},
    {"ko":"18 % 회색","en":"18 % gray","abbr":"","def":"평균적인 장면 반사율을 대표하는 표준 반사율. 노출계와 SNR 비교의 기준점으로 쓴다.","chapters":["design"]},
    {"ko":"웨이퍼당 다이 수","en":"Dies per wafer","abbr":"DPW","def":"웨이퍼 한 장에서 나오는 다이 개수. 원형 가장자리 손실 때문에 다이가 클수록 면적 비 이상으로 줄어든다.","chapters":["design"]},
    {"ko":"수율","en":"Yield","abbr":"Y","def":"만들어진 다이 중 양품 비율. 단순 포아송 모델에서 Y = exp(−다이 면적 × 결함 밀도)로, 큰 다이일수록 급격히 떨어진다.","chapters":["design"]},
    {"ko":"차량용 신뢰성 규격","en":"AEC-Q100 / ISO 26262","abbr":"ASIL","def":"AEC-Q100은 차량용 반도체의 온도·수명 신뢰성 시험 규격, ISO 26262는 기능 안전 표준(ASIL 등급)이다. 차량용 센서 설계의 필수 조건이다.","chapters":["design"]},
    {"ko":"Walden 성능 지수","en":"Walden figure of merit","abbr":"FoM_W","def":"ADC 전력을 변환률과 2^ENOB의 곱으로 나눈 값(J/conversion-step). 작을수록 효율적이며, 비트당 전력이 2배라는 가정을 담고 있어 저·중분해능 ADC 비교에 쓴다.","chapters":["design"]},
    {"ko":"Schreier 성능 지수","en":"Schreier figure of merit","abbr":"FoM_S","def":"SNDR + 10 log₁₀(대역폭/전력)(dB). 클수록 효율적이며, 열잡음 한계에서 비트당 전력이 4배가 되는 물리를 반영해 고분해능 ADC 비교에 적합하다.","chapters":["design"]},
    {"ko":"전력 예산","en":"Power budget","abbr":"","def":"센서 전력을 블록별(픽셀 바이어스, 컬럼 ADC, 램프·PLL, MIPI, ISP, DRAM, 누설) ‘횟수 × 회당 에너지’로 나눠 더한 표. 비트 수·화소 수·프레임률이 주요 손잡이다.","chapters":["design"]},
    {"ko":"열저항","en":"Thermal resistance","abbr":"θ","def":"소비 전력 1 W가 접합 온도를 주변보다 몇 °C 올리는지 나타내는 값(°C/W). 폰 카메라 모듈은 수십 °C/W이며, 열 시상수는 열저항과 열용량의 곱이다.","chapters":["design"]},
    {"ko":"열 폭주","en":"Thermal runaway","abbr":"","def":"온도 상승이 누설 전력을 늘리고 늘어난 전력이 다시 온도를 올리는 되먹임이 발산하는 상태. 루프 이득 θ·dP/dT가 1에 이르거나 T = T_a + θP(T)의 해가 사라지면 일어난다.","chapters":["design"]},
    {"ko":"카메라 범프","en":"Camera bump","abbr":"","def":"카메라 모듈 높이(렌즈 TTL + 센서·기판 여유)가 폰 몸체 안쪽 높이를 넘어 뒷면으로 튀어나온 부분. 같은 화각에서 센서 대각이 클수록 초점 거리와 TTL이 늘어 커진다.","chapters":["design"]},
    {"ko":"마이크로렌즈 시프트","en":"Microlens shift","abbr":"","def":"가장자리 픽셀에서 주광선각(CRA)에 맞춰 마이크로렌즈와 컬러 필터를 센서 중심 쪽으로 옮기는 설계. 스택 높이 h, 굴절률 n이면 대략 h·tan(arcsin(sin CRA / n))만큼 옮긴다.","chapters":["design"]},
    {"ko":"상대 조도","en":"Relative illumination","abbr":"RI","def":"화면 중심 대비 가장자리의 상면 조도 비. 근사적으로 cos⁴(주광선각)으로 떨어지며, 렌즈 셰이딩 보정이 되돌려야 할 양을 정한다.","chapters":["design"]},
    {"ko":"파레토 전선","en":"Pareto front","abbr":"","def":"한 지표를 나쁘게 하지 않고는 다른 지표를 좋게 할 수 없는 설계들의 집합. 설계 공간 탐색에서 점수와 원가처럼 상충하는 목표 사이의 최선의 선택지를 보여 준다.","chapters":["design"]},
    {"ko":"토네이도 차트","en":"Tornado chart","abbr":"","def":"기준 설계에서 변수를 하나씩 ±δ 흔들었을 때의 KPI 변화를 막대로 그려 큰 순서로 쌓은 민감도 그림. 한쪽만 긴 막대는 동작 영역 경계를 가리킨다.","chapters":["design"]},
    {"ko":"탄력성","en":"Elasticity","abbr":"ε","def":"변수 x가 1 % 변할 때 KPI K가 몇 % 변하는지, ∂ln K/∂ln x. 샷 노이즈 한계 SNR의 픽셀 피치 탄력성은 1, 다이 원가의 피치 탄력성은 약 2다.","chapters":["design"]},
    {"ko":"컴퓨테이셔널 포토그래피","en":"Computational photography","abbr":"","def":"여러 장의 프레임과 계산으로 센서·렌즈의 물리적 한계(노이즈, 해상도, 심도)를 넘는 촬영 기법의 총칭.","chapters":["computational"]},
    {"ko":"ZSL 링 버퍼","en":"Zero shutter lag ring buffer","abbr":"ZSL","def":"셔터를 누르기 전부터 최근 RAW 프레임을 순환 저장해 셔터 지연 없이 버스트를 제공하는 버퍼.","chapters":["computational"]},
    {"ko":"읽기 노이즈 페널티","en":"Read noise penalty","abbr":"","def":"같은 총 노출을 N장으로 나눠 읽을 때 읽기 노이즈 분산이 N배 쌓여 생기는 SNR 손실.","chapters":["computational"]},
    {"ko":"기준 프레임","en":"Reference frame","abbr":"","def":"버스트에서 다른 프레임을 정렬·병합하는 기준으로 삼는, 보통 가장 선명한 프레임.","chapters":["computational"]},
    {"ko":"블록 매칭","en":"Block matching","abbr":"","def":"기준 프레임의 타일을 다른 프레임 위에서 옮겨 가며 차이가 최소인 변위를 찾는 정렬 방법.","chapters":["computational"]},
    {"ko":"계층적 정렬","en":"Coarse-to-fine alignment","abbr":"","def":"영상 피라미드의 저해상도에서 구한 변위를 초기값으로 삼아 고해상도로 내려가며 정밀화하는 정렬.","chapters":["computational"]},
    {"ko":"강건 병합","en":"Robust merge","abbr":"","def":"프레임 간 차이를 노이즈 모델과 비교해 움직임·정렬 실패 영역의 가중치를 낮추는 병합.","chapters":["computational"]},
    {"ko":"유효 프레임 수","en":"Effective frame count","abbr":"N_eff","def":"병합 가중치 w_i로부터 1/Σw_i²로 정해지는, 화소별 실제 노이즈 저감에 해당하는 프레임 수.","chapters":["computational"]},
    {"ko":"모션 미터링","en":"Motion metering","abbr":"","def":"촬영 전 장면과 손의 움직임을 재서 프레임당 노출 시간과 프레임 수를 정하는 과정.","chapters":["computational"]},
    {"ko":"멀티프레임 초해상도","en":"Multi-frame super-resolution","abbr":"MFSR","def":"프레임 간 서브픽셀 시프트로 에일리어싱된 표본을 더 촘촘한 격자로 병합해 해상도를 되찾는 기법.","chapters":["computational"]},
    {"ko":"합성 심도","en":"Synthetic depth of field","abbr":"","def":"시차로 얻은 깊이 맵에 따라 화소별 착란원 크기의 블러를 계산해 얕은 심도를 흉내 내는 기능(인물 모드).","chapters":["computational"]},
    {"ko":"환각","en":"Hallucination","abbr":"","def":"학습 기반 처리가 측정되지 않은 디테일을 학습 통계에 따라 그럴듯하게 만들어 넣는 현상.","chapters":["computational"]},
    {"ko":"위상 상관","en":"Phase Correlation","abbr":"","def":"두 영상의 스펙트럼 곱을 크기로 나누어 위상 차이만 남긴 뒤 역변환해, 변위 위치에 생기는 피크로 평행 이동을 구하는 정렬 방법. 서브픽셀 위치는 피크 주변을 업샘플링해 얻는다. 노이즈뿐인 고주파에도 같은 무게를 주므로 저조도에 약하다.","chapters":["computational"]},
    {"ko":"루카스–카나데 방법","en":"Lucas–Kanade Method","abbr":"LK","def":"밝기 불변 가정을 1차 테일러 전개로 선형화하고 타일 안의 제곱 오차를 최소제곱으로 풀어 변위를 구하는 미분 기반 정렬. 큰 변위는 영상 피라미드의 거친 레벨부터 반복해 푼다.","chapters":["computational"]},
    {"ko":"구조 텐서","en":"Structure Tensor","abbr":"","def":"타일 안 기울기의 곱 ΣIx², ΣIxIy, ΣIy²로 이루어진 2×2 행렬. 두 고윳값이 모두 크면 정렬이 잘 정해지고, 하나가 0에 가까우면 그 방향의 변위가 정해지지 않는 개구 문제가 생긴다.","chapters":["computational"]},
    {"ko":"개구 문제","en":"Aperture Problem","abbr":"","def":"한 방향의 가장자리만 있는 영역에서는 가장자리를 따라 움직여도 영상이 변하지 않아 그 방향의 변위를 알 수 없는 현상. 정렬과 광류 추정의 기본적 한계다.","chapters":["computational"]},
    {"ko":"노출 융합","en":"Exposure Fusion","abbr":"","def":"노출이 다른 화면용 영상들을 대비·채도·잘 노출됨으로 정한 화소별 가중치로 직접 섞어 HDR 장면을 한 장에 담는 방법(Mertens 2007). 노출비와 톤 매핑이 필요 없지만 결과는 선형 복사휘도가 아니다.","chapters":["computational"]},
    {"ko":"라플라시안 피라미드","en":"Laplacian Pyramid","abbr":"","def":"영상을 가우시안 피라미드의 이웃 층 차이로 나눈 대역별 표현. 층마다 다른 넓이의 가중치로 섞은 뒤 다시 합치면 이음매 없는 영상 혼합을 얻는다.","chapters":["computational"]},
    {"ko":"디컨볼루션","en":"Deconvolution","abbr":"","def":"관측 y = k * x + n에서 알려진 블러 커널 k를 되돌려 x를 추정하는 일. 전달 함수가 작은 주파수에서 노이즈가 증폭되므로 정규화가 필요하다.","chapters":["computational"]},
    {"ko":"위너 디컨볼루션","en":"Wiener Deconvolution","abbr":"","def":"복원 필터 H*/(|H|²+K)로 블러를 되돌리는 선형 방법. K는 노이즈 대 신호 전력비로, 0이면 역필터가 되어 노이즈가 발산하고 크면 복원을 거의 하지 않는다.","chapters":["computational"]},
    {"ko":"리처드슨–루시 반복","en":"Richardson–Lucy Deconvolution","abbr":"RL","def":"푸아송 노이즈의 최대 우도를 곱셈 갱신으로 구하는 반복 디컨볼루션. 값이 음수가 되지 않고 반복 횟수가 정규화 역할을 하며, 너무 오래 돌리면 노이즈가 자라는 반수렴을 보인다.","chapters":["computational"]},
    {"ko":"흔들림 PSF","en":"Motion Blur PSF","abbr":"","def":"노출 동안 상이 센서 위에서 그린 궤적을 따라 머문 시간을 무게로 한 블러 커널. 스마트폰은 자이로 각속도를 적분해 궤적을 얻는다.","chapters":["computational"]},
    {"ko":"열 예산","en":"Thermal budget","abbr":"","def":"이후 공정이 넘지 말아야 하는 온도·시간의 한도로, 공정 순서를 정하는 제약이다.","chapters":["fabrication"]},
    {"ko":"에피 웨이퍼","en":"Epitaxial wafer","abbr":"","def":"고농도 기판 위에 결정 방향을 이어 저농도 실리콘층을 성장시킨 웨이퍼로, 픽셀 소자가 이 층 안에 만들어진다.","chapters":["fabrication"]},
    {"ko":"이온 주입","en":"Ion implantation","abbr":"","def":"도펀트 이온을 가속해 실리콘에 넣는 공정으로, 에너지가 깊이를 도즈가 양을 정한다.","chapters":["fabrication"]},
    {"ko":"투영 비정","en":"Projected range","abbr":"Rp","def":"주입된 이온이 멈추는 평균 깊이.","chapters":["fabrication"]},
    {"ko":"도즈","en":"Dose","abbr":"","def":"단위 면적당 주입한 이온 수(cm⁻²).","chapters":["fabrication"]},
    {"ko":"게터링","en":"Gettering","abbr":"","def":"금속 불순물을 소자 영역 밖의 고농도 영역이나 결함으로 끌어모아 가두는 것.","chapters":["fabrication"]},
    {"ko":"수소 패시베이션","en":"Hydrogen passivation","abbr":"","def":"실리콘–산화막 계면의 결합손에 수소를 붙여 계면 준위를 없애는 열처리.","chapters":["fabrication"]},
    {"ko":"직접 본딩","en":"Direct (fusion) bonding","abbr":"","def":"평탄한 산화막 표면끼리 접착제 없이 맞붙이고 열처리로 공유 결합시키는 웨이퍼 접합.","chapters":["fabrication"]},
    {"ko":"두께 편차","en":"Total thickness variation","abbr":"TTV","def":"웨이퍼 안에서 가장 두꺼운 곳과 얇은 곳의 두께 차이.","chapters":["fabrication"]},
    {"ko":"디싱","en":"Dishing","abbr":"","def":"CMP에서 구리 패드가 주변 산화막보다 더 깎여 오목해지는 현상으로, 하이브리드 본딩에서는 수 nm로 관리한다.","chapters":["fabrication"]},
    {"ko":"오버레이","en":"Overlay","abbr":"","def":"서로 다른 층 또는 두 웨이퍼의 패턴이 어긋난 정도.","chapters":["fabrication"]},
    {"ko":"결함 밀도","en":"Defect density","abbr":"D₀","def":"단위 면적당 다이를 죽이는 결함 수로, 포아송 수율은 exp(−A·D₀)다.","chapters":["fabrication"]},
    {"ko":"면저항","en":"Sheet resistance","abbr":"Rs","def":"얇은 도핑층의 저항을 두께와 무관하게 나타낸 값(Ω/□). 접합 위 층의 농도와 이동도를 깊이로 적분한 전도도의 역수다.","chapters":["fabrication"]},
    {"ko":"종횡비 의존 식각","en":"Aspect-ratio-dependent etching","abbr":"ARDE","def":"좁고 깊은 패턴일수록 반응 기체와 이온이 바닥까지 덜 닿아 식각 속도가 깊이에 따라 떨어지는 현상. DTI에서는 입구가 넓은 교차점이 선 트렌치보다 깊이 파인다.","chapters":["fabrication"]},
    {"ko":"Cu 리세스","en":"Cu recess (dishing)","abbr":"","def":"하이브리드 본딩 CMP 뒤 구리 패드가 산화막 표면보다 낮게 들어간 깊이. 0보다 크고 열팽창으로 메울 수 있는 수 nm 창 안에 들어야 패드가 이어진다.","chapters":["fabrication"]},
    {"ko":"배율 오차","en":"Magnification (run-out) error","abbr":"","def":"두 웨이퍼의 패턴 배율이 다르게 휘고 늘어나 중심에서 멀수록 커지는 계통 오버레이 성분. 1 ppm이면 반지름 150 mm에서 150 nm다.","chapters":["fabrication"]},
    {"ko":"브리징","en":"Bridging (microlens merging)","abbr":"","def":"리플로우 중 녹은 마이크로렌즈 수지가 이웃과 닿아 하나로 합쳐지는 불량. 섬 사이 틈이 좁을수록 CD 변동만으로 발생 확률이 급격히 커진다.","chapters":["fabrication"]},
    {"ko":"보이스 코일 모터","en":"Voice coil motor","abbr":"VCM","def":"자기장 속 코일에 전류를 흘려 생기는 로렌츠 힘으로 렌즈를 움직이는 액추에이터.","chapters":["module"]},
    {"ko":"TTL","en":"Total track length","abbr":"TTL","def":"첫 렌즈 면에서 센서 면까지의 거리로, 모듈 두께를 좌우하며 같은 화각에서 센서 대각선에 비례한다.","chapters":["module"]},
    {"ko":"AF 행정","en":"AF stroke","abbr":"","def":"무한대에서 최단 촬영 거리까지 초점을 맞추는 데 필요한 렌즈 이동 범위로 f²/(s−f)다.","chapters":["module"]},
    {"ko":"링잉","en":"Ringing","abbr":"","def":"감쇠가 작은 스프링-질량계가 스텝 구동 뒤 목표 위치 주변에서 진동하는 현상.","chapters":["module"]},
    {"ko":"입력 정형","en":"Input shaping","abbr":"","def":"구동 명령을 공진 반주기 간격의 여러 스텝으로 나누어 잔류 진동을 상쇄하는 기법.","chapters":["module"]},
    {"ko":"클로즈드 루프 AF","en":"Closed-loop AF","abbr":"","def":"홀 센서로 렌즈의 실제 위치를 재어 되먹임 제어하는 구동 방식으로 자세차와 링잉을 없앤다.","chapters":["module"]},
    {"ko":"자세차","en":"Posture difference","abbr":"","def":"중력이 스프링 지지 렌즈를 처지게 해 기기 방향에 따라 초점 위치가 달라지는 현상.","chapters":["module"]},
    {"ko":"광학식 손떨림 보정","en":"Optical image stabilization","abbr":"OIS","def":"자이로로 잰 회전을 따라 렌즈나 센서를 움직여 노출 중 상을 센서 위 같은 자리에 붙잡는 기술.","chapters":["module"]},
    {"ko":"전자식 손떨림 보정","en":"Electronic image stabilization","abbr":"EIS","def":"여유 영역을 두고 읽은 영상을 자이로 정보로 옮기거나 변형해 프레임 사이 흔들림을 줄이는 기술.","chapters":["module"]},
    {"ko":"억제비","en":"Suppression ratio","abbr":"SR","def":"OIS를 껐을 때와 켰을 때의 상 이동량의 비를 dB로 나타낸 값.","chapters":["module"]},
    {"ko":"폴디드 광학계","en":"Folded optics (periscope)","abbr":"","def":"프리즘으로 광로를 90° 꺾어 긴 초점거리를 기기의 넓은 방향으로 눕힌 망원 구조.","chapters":["module"]},
    {"ko":"액티브 얼라인","en":"Active alignment","abbr":"AA","def":"센서를 켠 채 MTF를 보며 렌즈를 5~6축으로 정렬한 뒤 UV로 접착제를 굳히는 조립 공정.","chapters":["module"]},
    {"ko":"루프 이득","en":"Loop Gain","abbr":"","def":"되먹임 루프를 한 바퀴 돈 전달 함수 L = C·P·(지연). |L|이 큰 주파수에서는 오차가 1/|1+L|로 줄고, |L| = 1이 되는 크로스오버 근처의 위상이 안정성을 정한다.","chapters":["module"]},
    {"ko":"감도 함수","en":"Sensitivity Function","abbr":"","def":"S = 1/(1+L). 되먹임이 외란과 오차를 몇 배로 줄이는지 나타낸다. OIS에서는 손떨림 대역의 |S|가 억제비를 정하며, 저주파에서 줄인 만큼 크로스오버 근처에 피크가 생긴다(워터베드 효과).","chapters":["module"]},
    {"ko":"위상 여유","en":"Phase Margin","abbr":"PM","def":"루프 이득의 크기가 1인 주파수에서 위상이 −180°까지 남은 여유. 작을수록 스텝 오버슈트와 감도 피크가 커지고 0 이하이면 불안정하다. 서보에서는 보통 30~60°를 목표로 한다.","chapters":["module"]},
    {"ko":"이득 여유","en":"Gain Margin","abbr":"GM","def":"위상이 −180°가 되는 주파수에서 루프 이득이 1보다 얼마나 작은지(dB). 구조 공진이나 지연이 있으면 줄어들며, 0 dB 이하이면 불안정하다.","chapters":["module"]},
    {"ko":"위상 앞섬 보상","en":"Lead Compensation","abbr":"","def":"영점을 극점보다 낮은 주파수에 둔 보상기 (1+s/ωz)/(1+s/ωp). 두 주파수의 기하평균에서 위상을 arcsin[(α−1)/(α+1)]만큼 올려, 공진 위에서 닫는 OIS·AF 서보의 위상 여유를 확보한다.","chapters":["module"]},
    {"ko":"헌팅","en":"Hunting","abbr":"","def":"콘트라스트 AF가 초점값 봉우리를 확인하려고 초점 위치를 지나쳤다 되돌아오는 왕복. 동영상에서는 화면이 선명해졌다 흐려지는 모습으로 녹화된다.","chapters":["module"]},
    {"ko":"무열화 설계","en":"Athermalization","abbr":"","def":"온도가 변해도 초점이 움직이지 않도록 렌즈 초점거리의 열 계수와 렌즈–센서 사이 기구의 열팽창(β_L = α_b)을 맞추는 설계. 플라스틱 렌즈는 굴절률 온도 계수가 커 유리 렌즈 혼용과 기구 재료 선택으로 상쇄한다.","chapters":["module"]},
    {"ko":"입사동","en":"Entrance Pupil","abbr":"","def":"물체 쪽에서 본 조리개의 상. 지름 D = f/N이며, 물체의 같은 각도 영역에서 카메라가 모으는 광자 수는 D²에 비례한다. 망원과 광각 크롭의 저조도 성능을 비교하는 기준이다.","chapters":["module","optics"]},
    {"ko":"지멘스 스타","en":"Siemens Star","abbr":"","def":"중심에서 퍼지는 쐐기 무늬를 번갈아 칠한 해상도 차트. 반지름이 작을수록 공간 주파수가 높아져, 원을 따라 잰 변조도로 한 장에서 여러 주파수의 MTF와 한계 해상도를 읽을 수 있다.","chapters":["module"]},
    {"ko":"마이크로볼로미터","en":"Microbolometer","abbr":"","def":"진공 속에 가는 다리로 띄운 저항막(VOx, a-Si)이 적외선을 흡수해 오른 온도를 저항 변화로 읽는 비냉각 열 검출 픽셀.","chapters":["invisible"]},
    {"ko":"잡음 등가 온도차","en":"Noise equivalent temperature difference","abbr":"NETD","def":"열화상 센서에서 SNR이 1이 되는 장면 온도 차이로, 비냉각 볼로미터는 F/1 기준 30~50 mK 수준이다.","chapters":["invisible"]},
    {"ko":"비균일 보정","en":"Non-uniformity correction","abbr":"NUC","def":"열화상 어레이의 픽셀별 이득·오프셋 편차와 센서 온도에 따른 드리프트를 흑체나 셔터 기준으로 바로잡는 보정.","chapters":["invisible"]},
    {"ko":"방사율","en":"Emissivity","abbr":"ε","def":"같은 온도의 흑체에 대한 물체의 복사 비율로, 불투명체에서는 1−ε만큼 주변 복사를 반사하므로 열화상 온도 측정의 핵심 변수다.","chapters":["invisible"]},
    {"ko":"대기의 창","en":"Atmospheric window","abbr":"","def":"수증기·CO₂ 흡수가 약해 대기가 투명한 파장 구간으로, 적외선에서는 3~5 µm(MWIR)와 8~14 µm(LWIR)가 대표적이다.","chapters":["invisible"]},
    {"ko":"신틸레이터","en":"Scintillator","abbr":"","def":"X선을 흡수해 가시광을 내는 변환층(CsI:Tl, GOS)으로, 두꺼울수록 흡수 효율은 오르고 빛 퍼짐으로 MTF는 떨어진다.","chapters":["invisible"]},
    {"ko":"직접 변환 검출기","en":"Direct-conversion detector","abbr":"","def":"a-Se·CdTe 같은 광도전체가 X선을 바로 전하로 바꾸고 전계로 화소 전극에 모아, 빛 퍼짐 없이 읽는 X선 검출기.","chapters":["invisible"]},
    {"ko":"검출 양자 효율","en":"Detective quantum efficiency","abbr":"DQE","def":"출력 SNR²과 입사 X선 양자의 SNR²의 비로, 같은 화질에 필요한 선량을 결정하는 X선 검출기 지표.","chapters":["invisible"]},
    {"ko":"광자 계수 검출기","en":"Photon-counting detector","abbr":"PCD","def":"X선 광자 하나의 전하 펄스를 문턱값과 비교해 세는 검출기로, 전자 노이즈를 배제하고 에너지 구간별 영상(스펙트럴 CT)을 얻는다.","chapters":["invisible"]},
    {"ko":"데이터 큐브","en":"Hyperspectral data cube","abbr":"","def":"공간 두 축과 파장 한 축을 가진 초분광 영상 I(x, y, λ)로, 푸시브룸·분광 스캔·모자이크 필터 등으로 얻는다.","chapters":["invisible"]},
    {"ko":"정규 식생 지수","en":"Normalized difference vegetation index","abbr":"NDVI","def":"(NIR − Red)/(NIR + Red)로 정의하는 분광 지수로, 건강한 식생은 0.8 안팎, 맨흙은 0.1~0.2다.","chapters":["invisible"]},
    {"ko":"선형 편광도 / 편광각","en":"Degree / angle of linear polarization","abbr":"DoLP / AoLP","def":"0·45·90·135° 편광 화소에서 구한 스토크스 파라미터로 계산하는 값으로 DoLP = √(S₁²+S₂²)/S₀, AoLP = ½·atan2(S₂, S₁).","chapters":["invisible"]},
    {"ko":"에지 확산 함수","en":"Edge spread function","abbr":"ESF","def":"날카로운 에지를 찍었을 때 에지에 수직한 방향의 밝기 단면. 슬랜티드 에지법은 이를 1/4 픽셀 간격으로 오버샘플해 얻고, 미분하면 선 확산 함수가 된다.","chapters":["iq"]},
    {"ko":"선 확산 함수","en":"Line spread function","abbr":"LSF","def":"가는 선 광원의 상 단면으로, ESF의 미분과 같다. LSF의 푸리에 변환 크기를 DC로 나눈 것이 그 방향의 MTF다.","chapters":["iq"]},
    {"ko":"공간 주파수 응답","en":"Spatial frequency response","abbr":"SFR","def":"카메라 시스템이 공간 주파수별로 대비를 얼마나 전달하는지 나타낸 곡선으로, ISO 12233은 슬랜티드 에지(e-SFR)와 사인 스타(s-SFR)로 잰다. 비선형 ISP가 들어간 카메라에서는 MTF 대신 이 이름을 쓴다.","chapters":["iq"]},
    {"ko":"MTF50","en":"MTF50 / MTF50P","abbr":"","def":"MTF가 0.5로 떨어지는 공간 주파수(cy/px 또는 lp/ph). 선명도 인상과 상관이 좋지만 샤프닝으로 쉽게 오르므로, 정점의 50 %에서 읽는 MTF50P를 함께 본다. 예: 가우시안 블러 σ = 0.6 px와 100 % 개구 픽셀이면 0.281 cy/px.","chapters":["iq"]},
    {"ko":"언샤프 마스크","en":"Unsharp mask","abbr":"USM","def":"원본에서 흐린 영상을 뺀 디테일을 양 a만큼 더하는 샤프닝. 전달 함수가 1 + a(1 − G(f))라 중간 주파수 MTF가 1을 넘고, 에지에 오버슈트·언더슈트(헤일로)를 만든다.","chapters":["iq"]},
    {"ko":"데드리브스 차트","en":"Dead leaves chart","abbr":"","def":"반지름 분포 ∝ r⁻³인 무작위 원판을 겹쳐 쌓은 척도 불변 텍스처 차트. 출력과 원본의 파워 스펙트럼 비(또는 교차 스펙트럼)로 텍스처 MTF를 구해, 에지 보존 NR의 텍스처 손실을 잰다.","chapters":["iq"]},
    {"ko":"텍스처 MTF","en":"Texture MTF","abbr":"","def":"저대비 무작위 텍스처에 대해 잰 MTF. 비선형 NR은 고대비 에지를 지키고 텍스처를 지우므로, 같은 카메라에서 에지 MTF50보다 텍스처 MTF50이 절반 이하로 나오기도 한다.","chapters":["iq"]},
    {"ko":"대비 감도 함수","en":"Contrast sensitivity function","abbr":"CSF","def":"공간 주파수(cycles/degree)별 사람 눈의 대비 민감도. 휘도 CSF는 약 4 cpd에서 정점인 띠통과형, 색 CSF는 저역 통과형이며, 어큐턴스와 시각 노이즈의 가중 함수로 쓴다.","chapters":["iq"]},
    {"ko":"시각 노이즈","en":"Visual noise","abbr":"","def":"CSF로 거른 휘도·색 노이즈를 가중 합산해 보는 조건까지 반영한 노이즈 지표(ISO 15739, IEEE 1858). 같은 σ라도 노이즈 입자가 굵을수록, 크게 볼수록 값이 커진다.","chapters":["iq"]},
    {"ko":"컬러체커","en":"ColorChecker","abbr":"","def":"피부·하늘·잎 같은 기억색, 원색, 6단계 회색으로 이루어진 24색 반사 차트. 카메라 색 정확도(ΔE00), 채도, WB 오차를 재고 CCM을 교정하는 표준적인 대상이다.","chapters":["iq"]},
    {"ko":"CIELAB","en":"CIE 1976 L*a*b* color space","abbr":"Lab","def":"XYZ를 기준 흰색으로 나눈 뒤 세제곱근으로 압축해 만든 근사적 지각 균일 색 공간. L*은 밝기(0~100), a*는 적–녹, b*는 황–청 축이며 두 색의 거리가 ΔE*ab다.","chapters":["iq"]},
    {"ko":"CIEDE2000 색차","en":"CIEDE2000 color difference","abbr":"ΔE00","def":"CIELAB 거리에 밝기·채도·색상 가중 함수와 파랑 영역 회전 항을 더한 색차 공식. 진한 파랑에서 ΔE*ab 4.0인 두 색이 ΔE00 2.04이듯 채도가 높을수록 ΔE*ab보다 작게 나온다.","chapters":["iq"]},
    {"ko":"조건 등색","en":"Metamerism","abbr":"","def":"분광이 다른 두 자극이 특정 조명·관찰자에서만 같은 색으로 보이는 현상. 센서 감도가 등색 함수의 선형 결합이 아니면 카메라의 조건 등색이 사람과 달라, 최적 CCM과 색 오차가 조명마다 바뀐다.","chapters":["iq"]},
    {"ko":"광전 변환 함수","en":"Opto-electronic conversion function","abbr":"OECF","def":"장면 휘도(또는 노출량)와 출력 코드의 관계(ISO 14524). 회색 스텝 차트로 재며, 톤 재현을 보여 주고 SFR 같은 선형 분석 전에 출력을 선형화하는 데 쓴다.","chapters":["iq"]},
    {"ko":"증분 SNR","en":"Incremental signal-to-noise ratio","abbr":"","def":"OECF의 기울기로 환산한 장면 기준 SNR, L·(dY/dL)/σ_Y. 톤 커브의 영향이 지워져 카메라 다이내믹 레인지를 정의하는 데 쓰며, ISO 15739는 SNR = 1을 하한으로 쓴다.","chapters":["iq"]},
    {"ko":"SMIA TV 왜곡","en":"SMIA TV distortion","abbr":"","def":"영상 양 끝 세로 길이의 평균 A와 가운데 세로 길이 B로 100(A − B)/B %로 정의한 왜곡. 배럴이면 음수이고 전통적인 TV 왜곡의 두 배다.","chapters":["iq"]},
    {"ko":"배율 색수차","en":"Lateral chromatic aberration","abbr":"LCA","def":"파장마다 배율이 달라 중심에서 멀수록 R·G·B 상이 방사 방향으로 어긋나는 수차. 점 격자의 채널별 중심 차나 에지의 색 경계 폭(ISO 19084)으로 재며, 0.5픽셀만 남아도 고대비 에지에 색 테두리가 보인다.","chapters":["iq"]},
    {"ko":"베일링 글레어","en":"Veiling glare","abbr":"VGI","def":"렌즈·경통·센서의 산란과 반사로 영상 전체에 퍼지는 미광. 밝은 영역 가운데 광 트랩의 출력 ÷ 흰 영역 출력(VGI)으로 재며, 선형 2.5 %도 sRGB 코드 약 44로 검은색을 띄우고 측정 DR을 약 5.3스톱으로 묶는다.","chapters":["iq"]},
    {"ko":"글레어 확산 함수","en":"Glare spread function","abbr":"GSF","def":"PSF 가운데 수십~수백 픽셀까지 넓게 퍼진 꼬리 성분. 에너지 비율 β만큼의 빛이 이 모양으로 퍼지며, 측정 VGI는 β에 차트의 밝은 영역 위 GSF 합을 곱한 값이라 β보다 작다.","chapters":["iq"]},
    {"ko":"셔터 지연","en":"Shooting time lag","abbr":"","def":"셔터 버튼을 누른 순간부터 실제 노출까지의 시간(ISO 15781). AF·AE와 프레임 경계 대기가 포함되며, 미리 초점을 맞춘 상태의 값은 셔터 릴리스 지연으로 따로 부른다. ZSL은 이를 0이나 음수로 만든다.","chapters":["iq"]},
    {"ko":"어큐턴스","en":"Acutance","abbr":"","def":"시스템 MTF를 보는 조건에 맞춘 CSF로 가중 평균한 선명도 지표(CPIQ). 같은 두 카메라도 출력 크기와 거리에 따라 순위가 바뀐다.","chapters":["iq"]},
    {"ko":"주관 화질 계수","en":"Subjective quality factor","abbr":"SQF","def":"Granger와 Cupery가 제안한 선명도 지표로, 약 3~12 cycles/degree 대역에서 MTF를 로그 주파수로 평균한 값(%). 샤프닝으로 MTF가 1을 넘으면 100을 넘을 수 있다.","chapters":["iq"]},
    {"ko":"최소 식별 차이","en":"Just noticeable difference","abbr":"JND","def":"쌍대 비교에서 관찰자의 75 %가 한쪽을 고르는 품질 차이(ISO 20462). 정규분포 모델에서 z = 0.6745에 해당하며, CPIQ는 객관 지표를 JND 단위 품질 손실로 바꿔 합친다.","chapters":["iq"]},
    {"ko":"평균 의견 점수","en":"Mean opinion score","abbr":"MOS","def":"관찰자들이 매긴 척도 점수(보통 5단계)의 평균. 주관 평가의 대표값이지만 척도 해석이 사람마다 달라, 차이를 정밀하게 재려면 쌍대 비교와 서스톤 척도를 쓴다.","chapters":["iq"]},
    {"ko":"CPIQ","en":"Camera Perceptual Image Quality (IEEE 1858)","abbr":"CPIQ","def":"폰 카메라 화질 표준(IEEE 1858-2023). SFR·텍스처·시각 노이즈·색·LCA·왜곡 등 지표를 JND 품질 손실로 바꾸고, 최악이 지배하는 다변량 공식으로 합친다.","chapters":["iq"]},
    {"ko":"프레넬 수","en":"Fresnel number","abbr":"N_F","def":"개구 반지름 a, 파장 λ, 거리 z로 정한 N_F = a²/(λz). 1보다 훨씬 크면 기하광학, 1 근처나 아래면 회절이 지배한다. 0.7 µm 픽셀 렌즈(f 1.2 µm, n 1.6)는 약 0.3이다.","chapters":["nanophotonics"]},
    {"ko":"각 스펙트럼법","en":"Angular spectrum method","abbr":"ASM","def":"장을 푸리에 변환해 평면파 성분으로 나누고 각 성분에 정확한 전파 인자 exp(iz√(k²−kₓ²))를 곱한 뒤 다시 합치는 스칼라 전파 계산법. 균질 매질에서는 근사가 없고 FFT로 빠르다.","chapters":["nanophotonics"]},
    {"ko":"FDTD","en":"Finite-difference time-domain","abbr":"FDTD","def":"공간을 격자로, 시간을 작은 스텝으로 나눠 맥스웰 회전 방정식을 차분식으로 직접 푸는 방법. 픽셀 광학 설계의 표준 도구로, 매질 속 파장당 셀 10~30개를 쓴다.","chapters":["nanophotonics"]},
    {"ko":"Yee 격자","en":"Yee lattice","abbr":"","def":"전기장과 자기장 성분을 반 칸씩 엇갈려 배치한 FDTD 격자. 회전 연산이 이웃 성분의 차분 하나로 끝나고, E와 H를 반 스텝씩 번갈아 갱신한다(립프로그).","chapters":["nanophotonics"]},
    {"ko":"Courant 조건","en":"Courant–Friedrichs–Lewy condition","abbr":"CFL","def":"명시적 FDTD가 안정하려면 시간 스텝이 cΔt/Δx ≤ 1/√d(d: 차원)를 만족해야 한다는 조건. 2-D 정사각 격자에서 0.707, Δx = 10 nm면 Δt ≤ 약 24 as다.","chapters":["nanophotonics"]},
    {"ko":"완전 정합층","en":"Perfectly matched layer","abbr":"PML","def":"계산 영역 끝에 두는 인공 흡수층. 전기·자기 전도도를 σ*/μ = σ/ε로 맞춰 계면 반사 없이 들어온 파동만 감쇠시킨다. 없으면 경계에서 되돌아온 빛이 결과를 오염시킨다.","chapters":["nanophotonics"]},
    {"ko":"블로흐 주기 경계","en":"Bloch periodic boundary","abbr":"","def":"무한 반복 구조를 한 주기만 계산할 때, 비스듬한 입사파의 위상차 e^{ikₓL}을 곱해 장을 반대편 경계로 넘겨주는 조건. 픽셀 배열의 경사 입사 FDTD·RCWA에 쓴다.","chapters":["nanophotonics"]},
    {"ko":"전달 행렬법","en":"Transfer-matrix method","abbr":"TMM","def":"가로로 균일한 다층 박막에서 층마다 2×2 특성 행렬을 곱해 반사·투과·층별 흡수를 정확히 구하는 방법. ARC 설계와 BSI 실리콘의 에탈로닝 계산에 쓴다.","chapters":["nanophotonics"]},
    {"ko":"파브리–페로 공진기","en":"Fabry–Pérot resonator","abbr":"FP","def":"두 반사면 사이를 오가는 빛이 간섭하는 공진기. 3 µm BSI 실리콘은 NIR에서 손실 있는 FP가 되어, 940 nm에서 약 34 nm 주기의 QE 리플을 만든다.","chapters":["nanophotonics"]},
    {"ko":"군굴절률","en":"Group index","abbr":"n_g","def":"n_g = n − λ dn/dλ. 펄스 포락선의 속도와 FP 리플 주기 Δλ ≈ λ²/(2n_g d)를 정한다. Si는 900 nm 부근에서 n ≈ 3.62, n_g ≈ 4.2이다.","chapters":["nanophotonics"]},
    {"ko":"도파 모드","en":"Guided mode","abbr":"","def":"고굴절 코어에 전반사로 갇혀 모양을 유지하며 진행하는 장의 고유 분포. DTI로 둘러싸인 0.6 µm 실리콘 기둥은 550 nm에서 TE 모드 9개를 갖는다.","chapters":["nanophotonics"]},
    {"ko":"V 수","en":"Normalized frequency","abbr":"V","def":"V = (πw/λ)√(n₁² − n₂²). 대칭 평판 도파로의 TE 모드 수는 ⌊2V/π⌋ + 1이다. 0.4 µm Si 코어·산화막 벽은 940 nm에서 V ≈ 4.4, 모드 3개다.","chapters":["nanophotonics"]},
    {"ko":"람베르트 한계","en":"Lambertian (Yablonovitch) limit","abbr":"4n²","def":"표면이 빛을 완전히 무작위화하고 뒷면이 완전 반사일 때 약흡수 극한에서 경로가 최대 4n²배 늘어난다는 한계. Si NIR에서 약 52배로, 3 µm Si의 940 nm 흡수를 5%에서 약 74%로 올린다.","chapters":["nanophotonics"]},
    {"ko":"역피라미드","en":"Inverted pyramid texture","abbr":"","def":"KOH 이방성 식각으로 Si 표면에 판 {111}면(54.7°)의 피라미드형 홈. 빛을 비스듬히 꺾어 경로를 늘리므로 NIR QE를 높이지만 표면적 증가로 암전류와 크로스토크가 는다.","chapters":["nanophotonics"]},
    {"ko":"유효 매질 이론","en":"Effective medium theory","abbr":"EMT","def":"주기가 파장보다 충분히 작은 구조를 평균 유전율의 균일 매질로 보는 근사. 1-D 격자에서 ε_TE = fε₁ + (1−f)ε₂, 1/ε_TM = f/ε₁ + (1−f)/ε₂로 편광마다 달라진다(형태 복굴절).","chapters":["nanophotonics"]},
    {"ko":"도파 모드 공진","en":"Guided-mode resonance","abbr":"GMR","def":"고굴절 격자층이 입사광을 도파 모드로 결합했다가 다시 방사하며 좁은 대역에서 거의 100% 반사하는 현상. SiN 격자(주기 320 nm)는 약 490 nm에서 반치폭 20 nm 정도의 반사 피크를 낸다.","chapters":["nanophotonics"]},
    {"ko":"RCWA","en":"Rigorous coupled-wave analysis","abbr":"RCWA","def":"주기 구조의 유전율을 푸리에 급수로 펼쳐 층 안 고유 모드를 구하고 경계 조건을 연립해 회절 차수별 반사·투과를 엄밀히 계산하는 방법. 격자·메타표면 설계의 표준 도구다.","chapters":["nanophotonics"]},
    {"ko":"메타표면","en":"Metasurface","abbr":"","def":"파장보다 작은 나노 기둥·구멍을 배열해 빛의 위상·진폭·편광을 국소적으로 바꾸는 평면 광학 소자. 기둥 폭으로 유효 굴절률을 바꿔 0~2π 위상 지도를 그린다(메타렌즈, 컬러 라우터).","chapters":["nanophotonics"]},
    {"ko":"역설계","en":"Inverse design","abbr":"","def":"목표 성능(예: 색별 픽셀 도달률)을 정하고 수반(adjoint) 기울기나 직접 이진 탐색(DBS)으로 구조를 자동 최적화하는 설계 방식. 메타표면·컬러 라우터 설계에 쓴다.","chapters":["nanophotonics"]},
    {"ko":"D-PHY","en":"MIPI D-PHY","abbr":"D-PHY","def":"카메라·디스플레이용 MIPI 물리층. 한 클록 레인(DDR 소스 동기)과 1–4 데이터 레인을 쓰며, 약 200 mV 차동의 HS 모드와 1.2 V 단일 종단의 LP 모드를 오간다. 레인당 2.5 Gbps(v1.2), 4.5 Gbps(v2.x), 약 9 Gbps(v3.0).","chapters":["interface"]},
    {"ko":"C-PHY","en":"MIPI C-PHY","abbr":"C-PHY","def":"세 선(트리오)에 세 레벨을 써서 여섯 와이어 상태를 매 심벌 바꾸는 MIPI 물리층. 클록을 심벌 전이에 내장하고 16비트를 7심벌로 보내 심벌당 2.286비트를 나른다. v2.x 표준 채널 6 Gsps ≈ 트리오당 13.7 Gbps.","chapters":["interface"]},
    {"ko":"레인","en":"Lane","abbr":"","def":"직렬 링크에서 독립적으로 데이터를 나르는 한 신호 경로(D-PHY는 차동 쌍 하나, C-PHY는 트리오 하나). 패킷 바이트는 레인에 돌아가며 분배되고 각 레인이 따로 버스트 시작·끝을 갖는다.","chapters":["interface"]},
    {"ko":"HS 모드","en":"High-speed mode","abbr":"HS","def":"D-PHY에서 데이터를 보내는 저전압 차동 모드(공통 모드·차동 진폭 약 200 mV, 종단 켬). LP-11 → LP-01 → LP-00 → HS-ZERO → 동기 B8h 순으로 진입하고 HS-TRAIL 뒤 LP-11로 돌아간다.","chapters":["interface"]},
    {"ko":"LP 모드","en":"Low-power mode","abbr":"LP","def":"D-PHY에서 두 선을 각각 1.2 V CMOS 신호로 쓰는 저전력 모드. 선 조합(LP-11, LP-01, LP-00 등)이 상태를 나타내며 블랭킹 중 대기, 버스트 경계 표시, 초저전력 상태에 쓴다.","chapters":["interface"]},
    {"ko":"데이터 식별자","en":"Data identifier","abbr":"DI","def":"CSI-2 패킷의 첫 바이트. 위 2비트가 가상 채널(VC), 아래 6비트가 데이터 형식(DT, 예: RAW10 = 2Bh, FS = 00h)이다.","chapters":["interface"]},
    {"ko":"가상 채널","en":"Virtual channel","abbr":"VC","def":"한 CSI-2 링크에 여러 영상 흐름(다른 카메라, HDR 노출, AF 데이터)을 섞기 위한 패킷 단위 채널 번호. 기본 2비트(4개)이며 CSI-2 v2.0부터 D-PHY에서 16개, C-PHY에서 32개로 확장됐다.","chapters":["interface"]},
    {"ko":"워드 수","en":"Word count","abbr":"WC","def":"CSI-2 긴 패킷 헤더의 16비트 필드로, 뒤따르는 페이로드의 바이트 수. 틀리면 패킷 경계를 잃으므로 헤더 ECC로 보호한다.","chapters":["interface"]},
    {"ko":"아이 다이어그램","en":"Eye diagram","abbr":"","def":"긴 의사 난수 비트열의 수신 파형을 2 UI 길이로 겹쳐 그린 그림. 눈의 세로 열림(아이 높이)은 전압 여유, 가로 열림(아이 폭)은 타이밍 여유를 나타내며 ISI·지터·잡음을 한눈에 보여 준다.","chapters":["interface"]},
    {"ko":"비트 오류율","en":"Bit error rate","abbr":"BER","def":"수신 비트 중 틀린 비트의 비율. 가우시안 잡음에서는 Q 인자로 BER = ½ erfc(Q/√2)이며, 고속 링크는 보통 10⁻¹² 이하를 목표로 한다.","chapters":["interface"]},
    {"ko":"지터","en":"Jitter","abbr":"","def":"신호 전이 시각의 흔들림. 크기가 한정된 결정성 지터(DJ: ISI, 듀티 왜곡, 주기 잡음)와 가우시안 랜덤 지터(RJ)로 나누며, BER 10⁻¹²에서 총 지터는 대략 DJ + 14.07 × RJ(RMS)다.","chapters":["interface"]},
    {"ko":"CTLE","en":"Continuous-time linear equalizer","abbr":"CTLE","def":"수신단의 아날로그 등화기. 영점과 극점으로 저주파를 상대적으로 깎고 나이퀴스트 근처를 올려 채널 손실의 기울기를 상쇄한다. ISI를 줄이는 대신 고주파 잡음도 키운다.","chapters":["interface"]},
    {"ko":"HTS","en":"Line length (line_length_pck)","abbr":"HTS","def":"한 라인의 길이를 픽셀 클록 수로 나타낸 값으로, 유효 폭 + 수평 블랭킹이다. 라인 시간 = HTS / 픽셀 클록.","chapters":["interface"]},
    {"ko":"VTS","en":"Frame length (frame_length_lines)","abbr":"VTS","def":"한 프레임의 총 행 수(유효 행 + 수직 블랭킹). 프레임 레이트 = 픽셀 클록 / (HTS × VTS). 롤링 노출은 VTS에서 작은 여유를 뺀 값을 넘을 수 없어, 더 긴 노출은 VTS를 늘린다.","chapters":["interface"]},
    {"ko":"그룹 홀드","en":"Grouped parameter hold","abbr":"","def":"여러 센서 레지스터 쓰기를 보류했다가 홀드를 풀 때 같은 프레임 경계에서 한꺼번에 래치하게 하는 기능. 노출·게인 묶음의 분할 적용과 멀티바이트 값의 찢김을 막지만, 레지스터별 반영 지연 차이는 따로 맞춰야 한다.","chapters":["interface"]},
    {"ko":"CCI","en":"Camera Control Interface","abbr":"CCI","def":"MIPI 카메라의 레지스터 제어 버스. I²C 호환 2선 버스로 7비트 주소, 16비트 레지스터 주소, 8비트 데이터를 쓰며 100 kHz–1 MHz로 동작한다. 최신 센서는 I3C로도 접근한다.","chapters":["interface"]},
    {"ko":"임베디드 데이터","en":"Embedded data","abbr":"","def":"센서가 프레임마다 FS 직후(또는 끝)에 보내는 비영상 라인(CSI-2 DT 12h). 적용된 노출·게인·프레임 번호·온도 등을 담아 ISP가 어느 설정이 어느 프레임에 적용됐는지 알게 한다.","chapters":["interface"]},
    {"ko":"하드웨어 프레임 동기","en":"Hardware frame synchronization","abbr":"","def":"주 센서의 수직 동기(XVS) 출력이나 외부 트리거로 여러 센서의 프레임 시작을 맞추는 방법. 독립 클록의 ppm 드리프트를 매 프레임 지워 잔차를 라인 시간 이하로 줄인다.","chapters":["interface"]},
    {"ko":"SerDes","en":"Serializer/Deserializer","abbr":"SerDes","def":"카메라 모듈의 CSI-2를 동축·차폐 연선 한 가닥의 수 Gbps 직렬 신호로 바꿔 수–15 m 보내고 다시 푸는 칩 쌍. 전원(PoC)과 I²C·프레임 동기 역방향 채널을 함께 나른다.","chapters":["interface"]},
    {"ko":"A-PHY","en":"MIPI A-PHY","abbr":"A-PHY","def":"차량용 장거리 카메라·디스플레이 링크를 위한 MIPI SerDes 물리층 표준. v1.0이 최대 16 Gbps, v1.1이 이중 차동 쌍 케이블로 32 Gbps까지 정의하며 그 위에 CSI-2를 얹는다.","chapters":["interface"]},
    {"ko":"SLVS-EC","en":"Scalable Low Voltage Signaling with Embedded Clock","abbr":"SLVS-EC","def":"고해상도 산업·방송용 센서에 쓰이는 내장 클록 고속 직렬 인터페이스. 8b/10b 부호로 클록을 데이터에 넣어 레인 사이 스큐 제약 없이 여러 레인을 묶는다.","chapters":["interface"]},
  ]
};
